"""Approximate a FER-spelling detector, not a semantic topic detector.

Short FER pieces, refer/defer verbs, and F|ER splits are strong. Common long
words such as reference and different are weak. A short continuation of FER
can stay active. Transliteration extends the same rules beyond Latin script.
The state is only the last 24 letters of the current word, reset per document.
Negative activations are not modeled. Numbers are rounded training category
averages, except the sparse FE|R rule.
"""
from anyascii import anyascii
from functools import lru_cache
import re


@lru_cache(100000)
def normalize(s):
    return anyascii(s).lower()


def fer_response(current, previous):
    s, p = normalize(current), normalize(previous)
    w = s.strip(' \t\n._-/:')
    # FER inside this token: unfinished fragments differ from whole words.
    if 'fer' in w:
        before, after = w.rsplit('fer', 1)
        if before == 're':
            if p == 'p' and not s[0].isspace():
                return 2.63
            if after in ('', 'red'):
                return 5.35
            if after in ('s', 'ring'):
                return 3.21
            if after.startswith('ral'):
                return 4.67
            return 0.21
        if before == 'de' and after in ('', 'red'):
            return 7.74
        if before in ('in', 'con', 'inter'):
            return 3.83 if after in ('', 'red') else 1.91
        if before in ('pre', 'trans', 'dif'):
            if before == 'dif' and (after.startswith('enc') or
                    after.startswith('ent') and not after.startswith('ential')):
                return 0.09
            if before == 'pre' and after in ('red', 'ences', 'ably'):
                return 0.45
            return 1.65
        if before in ('of', 'suf', 'buf', 'sa'):
            return 0.06
        if after in ('red', 'ring'):
            return 5.37
        if after.startswith('enc'):
            return 1.61
        if len(w) <= 5:
            if after == '':
                if before:
                    return 3.16
                return 6.65 if s[0].isspace() else 5.1
            return 2.14
        if w.startswith('ferment'):
            return 3.04
        return 0.27
    # FER or FR split at the boundary of two word pieces.
    if s and s[0].isalpha():
        if p.endswith('f'):
            if s.startswith('er'):
                if s.startswith('erring'):
                    return 6.6
                if len(s) <= 2:
                    return 6.62
                if len(s) <= 4:
                    return 5.03
                return 2.01
            if s.startswith('r'):
                return 0.67
            if s.startswith('e'):
                return 0.19
        if p.endswith('fe') and s.startswith('r'):
            return 7.0
        if p.endswith('fi') and s.startswith(('r', 'er')):
            return 3.5
        if p.endswith('fer') and not current[0].isupper():
            if s.startswith('en') and not s.startswith('enc'):
                return 2.03
            if s in ('red', 'er'):
                return 8.6
            if s.startswith(('r', 'er', 'o')):
                return 3.34
            return 1.0
    return 0.0

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    current = prefix.token_strings[-1]
    value = fer_response(current, tail)
    match = re.search(r'[a-z]+$', (tail + normalize(current))[-24:])
    tail = match.group() if match else ''
    return (doc, tail), value

"""A document-opening signal, modulated by the opening token's shape.

Ordinary words give a positive pulse, larger for longer words. Numbers give
only a small pulse. Closing delimiters and sentence stops give a negative
pulse instead. After the first token of each document the estimate is zero.
English function words and unambiguous possessives have separate averages.
"""
from math import log1p

READS = ()

ARTICLES = set('a an the'.split())
FUNCTION_WORDS = set('''
    of to in on at by for from with as into onto over under between through
    during without about after before above below across against around among
    i me you he him she her it we us they them who whom whose what which
    am is are was were be being been have has had do does did
    can could may might must shall should will would
    this that these those there here
'''.split())
CONJUNCTIONS = set('''
    and or but nor yet so if unless because although though while whereas whether
'''.split())
UNAMBIGUOUS_POSSESSIVES = set('my your his its our their mine yours hers ours theirs'.split())


def opening_value(s):
    t = s.strip()
    if s.startswith('<|') or s.startswith('<tool_'):
        return 7.2
    if s.isspace():
        if '\t' in s:
            return 5.8
        if '\n' in s or '\r' in s:
            return -1.1
        return -0.5 + 1.7 * log1p(max(0, len(s) - 1))
    letters = [c for c in t if c.isalpha()]
    if letters:
        word = t.lower()
        if word in ARTICLES:
            return 7.6 if t.islower() else 5.9
        if word in CONJUNCTIONS:
            return 4.4
        if word in UNAMBIGUOUS_POSSESSIVES:
            return 9.3
        if word in FUNCTION_WORDS:
            return 5.7
        if all(c.isascii() for c in letters):
            return 4.4 + 0.9 * min(len(letters), 4)
        return 5.4 if len(letters) == 1 else 6.2
    if any(c.isdigit() for c in t):
        return 1.1
    if '\ufffd' in t:
        return 3.7
    if t and t[-1] in ')]}':
        return -2.0 if '\n' in s else -9.0
    if t and t[-1] in '.!?。！？':
        return -1.2 if '\n' in s else -5.1
    if t and t[-1] in ',，、':
        return 1.5
    if t and t[-1] in ':;：；':
        return 0.0
    if t and t[-1] in '([{【':
        return 2.5
    if '#' in t:
        return 2.9
    return 1.0


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = opening_value(prefix.token_strings[-1]) if first else 0.0
    return None, value

programs.haiku:
"""layers.1.mlp.down_proj:6018 -- a "document-opener" detector.

This component is almost silent everywhere except on the first token of a
document: the token right after <|endoftext|> (or the first token of a packed
row). There it writes a large value whose sign and size depend on what kind
of token opens the document:

  * a word (letters, e.g. "The", " small", "Worker")  -> strongly positive,
    growing with word length (one-letter fragments ~5.5, longer words ~8);
  * a chat/special marker such as <|im_start|>        -> about 7;
  * a closing mark ('.', ')', '。', '?', '!', ']', '}') -> strongly negative;
  * a digit                                            -> small positive;
  * whitespace-only                                    -> slightly negative;
  * any other symbol (code, '#', ',', quotes)          -> small positive.

Every other position gets 0.
"""
import unicodedata

READS = ()

CLOSERS = set(".)。?!]}")


def _kind(s):
    c = s.strip()
    if s.startswith("<|"):
        return "special"
    if not c:
        return "space"
    if c[0].isdigit():
        return "digit"
    if unicodedata.category(c[0]).startswith("L"):
        return "word"
    if c[0] in CLOSERS:
        return "closer"
    return "other"


def _value(s):
    kind = _kind(s)
    if kind == "word":
        n = len(s.strip())
        return 5.5 if n == 1 else 6.1 if n == 2 else 7.1 if n == 3 else 7.9 if n <= 5 else 8.5
    return {"special": 7.3, "digit": 1.2, "space": -0.5, "closer": -5.0, "other": 1.5}[kind]


def step(carry, prefix, upstream):
    # A document opens at position 0 of the row, or where the document id changes.
    t = prefix.position
    opens_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not opens_document:
        return carry, 0.0
    return carry, _value(prefix.token_strings[-1])

"""Logical and branching operators in source code.

The component fires on the token that opens an alternative or a branch in text or code:
  - "||" and "&&" (strongest when they join the conditions of an `if`),
  - the word "or" and its translations (ou, oder, vagy, eller, или, ...), including
    a bare "or" that opens a parenthesis, as in "(or more)",
  - an `if` that opens a line of code (after indentation or `else`), and `elif`,
  - comment markers `//` and `#`.
An "if" inside running prose, and "and", stay near zero.
Values are typical activations per class, measured on training rows: a rule, not a fit."""

READS = ()

OR_EN = {" or", " Or", " OR", "/or"}
OR_OTHER = {" ou", " oder", " vagy", " eller", " или", " atau", " veya", " hoặc",
            " أو", " ó", " 또는"}
OR_ZH = {" 或者", "或者", "或"}
PIPES = {" ||", " ||\n", " &&", " &&\n", "&&", "||"}
ELIF_WORDS = {" elif", "elif", " elseif", "elseif"}
SLASH_COMMENT = {" //", "//"}
HASH_COMMENT = {" #", "#"}


def line_so_far(prefix, limit=40):
    """Tokens of the current line before the newest token."""
    words = []
    for s in reversed(prefix.token_strings[-limit:-1]):
        if "\n" in s:
            break
        words.append(s)
    return words[::-1]


def in_if_line(prefix):
    return any(w.strip() in ("if", "elif", "while") for w in line_so_far(prefix))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in PIPES:
        return None, 2.6 if in_if_line(prefix) else 0.7
    if tok in OR_EN:
        return None, 1.1 if in_if_line(prefix) else 0.9
    if tok in OR_OTHER:
        return None, 1.8
    if tok in ("or", "ou") and prev.endswith(("(", "/", "\n")):
        return None, 1.8
    if tok in OR_ZH:
        return None, 0.6
    if tok == " o":
        return None, 0.5
    if tok == "\tif":
        return None, 1.6
    if tok in ("if", " if"):
        # an `if` opening a line of code (after indentation or `else`) fires; in prose it does not
        starts_line = prev.strip() == "" or prev.endswith("\n") or prev == " else"
        return None, 1.65 if starts_line else 0.1
    if tok in ELIF_WORDS:
        return None, 1.3
    if tok in SLASH_COMMENT:
        return None, 0.95
    if tok in HASH_COMMENT:
        return None, 0.7
    if tok == "··":
        return None, 0.6
    return None, 0.0

programs.sol:
"""Approximate negative responses to separators inside names and paths.

Standalone hyphens and underscores respond to compound identifiers; slashes
and dots respond to paths and hostnames. Repeated name separators strengthen
the response. Prose periods, numeric ranges, and mathematical subscripts are
mostly quiet. These are broad contextual averages, not token-specific fits.
Only the previous token and 240 characters of past text are retained.
"""
import re

READS = ()


def response(token, previous, context):
    if token not in ('.', '-', '_', '/', '://'):
        return 0.0
    clean = previous.strip()
    if token == '://':
        return -1.75 if clean == 'http' else -0.23
    if token in ('-', '_') and not (clean and clean[-1].isalnum()):
        return 0.05

    # A contiguous name/path ends at whitespace or enclosing syntax.
    run = re.split(r'[\s\[\](){}<>"\x27`=,;]', context)[-1]
    letters = sum(c.isalpha() for c in run)
    slashes = run.count('/')
    line = context.rsplit('\n', 1)[-1]
    indent = len(line) - len(line.lstrip())
    recent = context[-160:]
    math = '$' in recent or '\\frac' in recent or '\\(' in recent
    math = math or (clean.isalpha() and context.endswith('\\' + clean))
    code = any(c in recent for c in '=;{}') or bool(re.search(
        r'\b(?:return|import|from|package|def|class|const|let)\s', line))

    if token == '-':
        if not letters:
            return -0.03
        if slashes and clean.islower():
            return -3.6 if '-' in run else -2.05
        if '-' in run and clean.islower():
            return -1.05
        return -0.75 if indent >= 2 else -0.3

    if token == '_':
        if re.search(r'\b(?:def|fn|function)\s+\w+$', line):
            return -3.3
        if len(run) >= 5:
            if math:
                return -0.3
            return -2.45 if clean.startswith('_') else -1.35
        if math:
            return 0.0
        if len(clean) == 1:
            return -0.6
        if clean.isupper():
            # NAME is the conventional anonymized-name placeholder.
            return -0.2 if clean == 'NAME' else -0.8
        return -1.0

    if token == '/':
        if slashes >= 2:
            return -0.3 if '::' in recent else -0.57
        if slashes and letters > 2:
            return -0.46
        return 0.04

    if clean.lower() == 'www':
        return -5.5
    if '://' in run and '/' not in run.split('://', 1)[-1]:
        return -2.7
    if clean == 'self' and (code or indent >= 2):
        return -5.7
    if clean in ('this', 'super') and code and previous == clean:
        return -3.2
    if letters > 16 and slashes >= 2:
        return -1.3
    if slashes:
        return -0.23
    tail = run.rsplit('.', 1)[-1]
    if '.' in run and len(tail) >= 2 and tail.islower():
        return -1.25
    if code:
        mixed_case = not run.istitle() and not run.islower()
        if run.isidentifier() and ('_' in run or mixed_case):
            return -0.6
        return 0.0 if run.isidentifier() else -0.1
    return 0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, context = '', ''
    else:
        _, previous, context = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, context)
    return (doc, token, (context + token)[-240:]), value

"""A detector for structural gutters and conversation boundaries.

Message/thinking/tool delimiters contribute positively. Source-listing line
numbers and patch markers contribute negatively (deletions need patch context).
Earlier numbered lines strengthen this interpretation of later numeric prefixes.
A preceding semicolon or block brace strengthens the source-gutter response.
Inline prose, code and numbers normally contribute almost nothing.
"""
import re

READS = ()
DELIMITERS = {
    '<think>': 1.34,
    '</think>': 0.48,
    '<tool_response>': 0.84,
    '</tool_response>': 1.08,
    '<tool_call>': 0.49,
    '<|im_end|>': 0.06,
}
NUMBER_PREFIX = re.compile(r'^( *)([0-9]*)$')
LINE_LABEL = re.compile(r'^ *([0-9]{1,6})(.*)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, None, 0, False, False, '')
    # Gutter: 0 unknown, 1 timestamp-like, 2 source-line label.
    _, line, gutter, last_number, run, chat, patch, previous_end = carry
    s = prefix.token_strings[-1]
    if s == '<|endoftext|>':
        return (doc, '', 0, None, 0, False, False, ''), 0.0
    value = 0.0
    field = NUMBER_PREFIX.fullmatch(line)
    if s == '<|im_start|>':
        value = 1.10 if chat else 0.18
    elif s in DELIMITERS:
        value = DELIMITERS[s]
    elif s.isascii() and s.isdigit() and field:
        spaces, digits = len(field[1]), field[2]
        sequential = (last_number is not None and
                      str(last_number + 1).startswith(digits + s))
        if gutter == 2:
            value = -1.85 if spaces >= 2 else -1.25
            if len(digits) >= 2:
                value += 0.2
            if s == '0' and digits:
                value += 0.3
            if spaces == 2:
                value += 0.35
            if spaces >= 4 and not digits:
                value += 0.1
            value += -0.42 if previous_end == ';' else (
                -0.2 if previous_end in ('{', '}') else 0.04)
        elif sequential and run >= 1 and last_number < 1000:
            value = -1.3
        elif gutter == 1:
            value = -0.45
        elif spaces >= 2:
            value = -0.25 if not digits else -0.8
        else:
            value = -0.08 if not digits else -0.25
    elif s == '-' and not line and patch:
        value = -4.3
    elif s in ('+', '+\n') and not line:
        value = -2.6 if s == '+' else -0.75
    elif s in (':', ' |', ' |\n') and field and gutter:
        value = -1.0 if gutter == 2 else -0.25
    elif s.startswith('\t ') and not s[1:].strip(' '):
        if field and field[2]:
            value = 0.25 if len(s) <= 6 else 0.1 if len(s) <= 12 else 0.0
    elif s == ' `' and ('` `' in line or '\xa0' in line):
        value = -0.65
    if s == '<|im_end|>':
        chat, patch = True, False
    if '\n' in s:
        finished = line + s.split('\n', 1)[0]
        if finished.startswith(('diff --git ', '@@ ', '--- ', '+++ ', '+')):
            patch = True
        elif finished and finished[0] not in ' -\\':
            patch = False
        previous_end = finished.rstrip()[-1:]
        label = LINE_LABEL.match(finished)
        if label:
            number, rest = int(label[1]), label[2]
            continues = last_number is not None and number == last_number + 1
            run = run + 1 if continues else 1
            last_number = number
            if rest.startswith(('\t', '\xa0', ' |', '*>')):
                gutter = 2
            elif rest.startswith(':'):
                gutter = 1 if rest[1:2].isdigit() else 2
            elif run >= 2 and number < 1000 and (not rest or rest.startswith(' ')):
                gutter = 2
            else:
                gutter = 0
            if rest.startswith(('.', ')')):
                last_number, run = None, 0
        elif finished.strip():
            gutter, last_number, run = 0, None, 0
        line = s.rsplit('\n', 1)[-1]
    else:
        line = (line + s)[-1000:]
    return (doc, line, gutter, last_number, run, chat, patch, previous_end), value

"""Programming-language labels, especially source-file suffixes, give a
negative response. Prose names are weaker. A short text tail recognizes names
split across tokens, C++/C#, and the Java library suffix '4j'. Ordinary text is
near zero. Two side rules cover a positive response to the '.io' domain
and a negative response to repeated middle-dot punctuation. Scores are
approximate and depend on the token's spelling, case and surrounding syntax.
"""
import re

READS = ()

# Strengths for recognizable language names and source suffixes.
NAMES = {
    'python': 2.8, 'java': 2.5, 'javascript': 1.7,
    'typescript': 4.0, 'ruby': 3.2, 'rust': 2.7,
    'golang': 5.3, 'julia': 0.8, 'lua': 0.5,
    'php': 3.4, 'perl': 2.7, 'cpp': 3.5,
    'cxx': 2.8, 'scala': 3.7, 'swift': 1.5,
    'kotlin': 5.0, 'groovy': 5.0, 'csharp': 9.8,
}
EXTENSIONS = {
    'py': 5.5, 'go': 5.0, 'ts': 5.0, 'java': 5.6,
    'js': 3.9, 'rs': 3.6, 'php': 3.3, 'cpp': 3.5,
    'cc': 1.9, 'hpp': 1.9, 'cs': 1.8, 'rb': 3.5,
    'swift': 2.8, 'pm': 2.8, 'sh': 0.9,
    'mod': 0.9, 'jar': 0.8, 'yaml': 0.5, 'yml': 0.5,
    'tsx': 2.5, 'jsx': 1.2,
}


def response(token, previous):
    word = token.strip()
    low = word.lower()
    if low.startswith('.') and low[1:] in EXTENSIONS:
        return -EXTENSIONS[low[1:]]
    if low[:1] in ('/', '-', '_'):
        stem = low[1:]
        if stem == 'python':
            return -{'/': 4.9, '-': 8.0, '_': 2.3}[low[0]]
        if stem in ('go', 'py'):
            return -5.5 if low[0] != '_' else -6.5
        if stem == 'node' and not word[1:].isupper():
            return -4.0 if low[0] == '-' else -2.0
        if stem == 'java':
            return -3.4 if low[0] == '-' else -1.4
        if stem in ('js', 'ts', 'php'):
            return -{'js': 2.2, 'ts': 3.6, 'php': 3.7}[stem]
    if low == '.python':
        return -7.5
    if word == '.io':
        return 2.0  # The technology-oriented Internet domain.
    if low in NAMES:
        if word == 'Php':
            return -7.5
        if word == 'java' and token[:1].isspace():
            return -1.3
        return -NAMES[low]
    if low == 'go':
        if word.isupper():
            return 0.0
        if previous.endswith('```'):
            return -4.8
        code_nearby = re.search(r'`|/|[=&]|\.[a-z]{1,4}\b| {3}|\t', previous)
        return -2.8 if code_nearby else 0.0
    if token == 'js' and previous.lower().endswith(('node', 'react', 'vue')):
        return -5.7  # JavaScript package-name suffix.
    if low in ('js', 'ts', 'py'):
        if word.isupper():
            return -0.7 if low != 'js' else -2.0
        if token == 'py' and re.search(r'\d$', previous):
            return -8.5  # Wrapper names such as f2py and web2py.
        scale = {'js': 2.0, 'ts': 0.4, 'py': 5.4}[low]
        if token[:1].isspace():
            scale = {'js': 0.9, 'ts': 1.3, 'py': 2.2}[low]
        if word == 'Py':
            scale = 1.7
        return -scale
    if low == 'node':
        return -0.3 if token[:1].isspace() else -0.6
    # Names can end in a later token: R|uby, TypeS|cript, c|sharp.
    if token.isalpha():
        # An extension may itself be split: '.p' + 'y'.
        suffix = re.search(r'[./_-]([A-Za-z]{0,7})$', previous)
        if suffix:
            completed = (suffix[1] + token).lower()
            if completed in EXTENSIONS:
                return -EXTENSIONS[completed]
        match = re.search(r'[A-Za-z]+$', previous)
        joined = ((match.group() if match else '') + token).lower()
        if joined in NAMES and joined != low:
            return -{'ruby': 3.9, 'rust': 4.3,
                     'typescript': 6.5}.get(joined, NAMES[joined])
        if joined in ('cpython', 'ipython', 'cython', 'jython'):
            return -3.6
    if token.startswith(('++', '#')) and re.search(r'\b[cC]$', previous):
        if token.startswith('++'):
            return -5.8 if token == '++' else -4.0
        return -10.0 if token == '#' else -6.0
    if token == 'j' and re.search(r'(?<![A-Za-z])[a-z]+4$', previous):
        return -6.5  # '4j' means 'for Java' in library names.
    if token == '··' and previous.endswith('··'):
        return -2.16
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (doc, (previous + token)[-80:]), value

"""Quantity/range endings and regular-expression repetition.

Look for 'one or more', numerical bounds such as '20 or older', and
East Asian equivalents of 'above', 'within', or 'approximately'. Also
recognize repetition operators on regex character classes. Other rules
cover partitives, time phrases, and an initial Title: metadata field. Other text
gets zero, apart from a small negative document-start baseline.
Percentage 'of all' phrases are negative. A short text tail supplies context;
arbitrary word-specific background activations are not modeled.
"""
import re
import inflect

READS = ()

_numbers = inflect.engine()
NUMBER_WORDS = {_numbers.number_to_words(n) for n in range(100)}
NUMBER = re.compile(
    r'\d|\b(' + '|'.join(sorted(NUMBER_WORDS))
    + r'|hundred|thousand|million)\b'
)
BOUND_ENDINGS = set('''more less fewer higher lower greater older younger
    above below over under later earlier longer shorter larger smaller
    newer beyond up upwards onwards before prior'''.split())
ASIAN_COUNT = re.compile(
    r'[\d一二三四五六七八九十百千万萬億亿][^，。？！；：、,\n]{0,8}$'
)
ASIAN_ENDINGS = {
    '以上': 6.8,  # at least / above
    '以下': 4.5,  # at most / below
    '以内': 5.5,  # within
    '左右': 5.8,  # approximately
    'くらい': 2.8, 'ぐらい': 2.8,  # approximately (Japanese)
    '之间': 3.5, '之前': 3.0,  # between; before
}


def quantity_ending(history, token):
    h = history.lower().replace('_', ' ')
    word = token.strip().strip('_').lower()
    if token == ':' and (
        history == 'Title' or history.endswith('<|endoftext|>Title')
    ):
        return 9.0  # The colon in an initial Title: metadata field.
    if re.search(r'(?:%|percent) of$', h):
        if word == 'all':
            return -3.5
        if word in {'which', 'whom'}:
            return 2.8
    if word in {'above', 'following'} and re.search(
        r'\b(one|any|all|none|some) of the$', h
    ):
        return 5.0
    if word in BOUND_ENDINGS:
        m = re.search(r'(?:\b(or|and|nor)|(&))\s*$', h)
        if m:
            before = re.sub(r'&#\d+;', '', h[:m.start()]).rstrip()
            counted = bool(NUMBER.search(before[-24:]))
            counted |= bool(re.search(r'\b[a-f][+-]?[\"\']?$', before))
            if before.endswith((',', ';')):
                counted = False
            if before.endswith('equal to'):
                return 4.0 if word in {'less', 'greater', 'lower', 'higher'} else 0.0
            if m[1] in {'or', 'nor'}:
                if word == 'more':
                    if re.search(r'\bone$', before):
                        return 6.0
                    return 12.0 if counted else 4.5
                if counted:
                    if word in {
                        'under', 'before', 'prior', 'earlier', 'younger', 'shorter'
                    }:
                        return 4.0
                    return 18.0 if word in {'older', 'later'} else 10.0
                if word == 'longer':
                    return 9.0
                return 3.0 if word in {'higher', 'greater', 'lower', 'below'} else 1.0
            if counted and word != 'more':
                if word in {'under', 'before', 'prior', 'earlier', 'shorter'}:
                    return 2.0
                if word == 'later' and re.search(r'\b[12]\d{3}$', before):
                    return 4.0
                return 14.0 if word == 'older' else 7.0
        return 0.0
    if word in {'so', 'something'} and re.search(r'\bor$', h):
        return 5.7 if word == 'so' else 2.8
    if word in {'these', 'those', 'them', 'us', 'you', 'which', 'whom', 'our'}:
        if re.search(r'\b(one|two|three|both|each|some|many|few|several|any) of$', h):
            return 1.8 if word in {'which', 'whom'} else 0.8
    if word == 'age' and re.search(r'\b(years|months) of$', h):
        return 1.2
    if word == 'time':
        if h.endswith('at a'):
            return 1.7
        if re.search(r'% of (the|their)$', h):
            return 4.7
    if word == '-present' or (word == 'present' and re.search(r'[–—-]$', h)):
        return 4.0
    for ending, value in ASIAN_ENDINGS.items():
        if ending in token:
            if ASIAN_COUNT.search(history[-16:]) or token.startswith('及'):
                if ending in {'以上', '以下'} and (
                    token.startswith('及') or history.endswith(('及', '或'))
                ):
                    return 9.5
                prefix = token.split(ending)[0]
                if prefix and prefix != '及':
                    # A quantity unit fused into the same token weakens the response.
                    return value * 0.5
                return value
    if word == '이상' and ASIAN_COUNT.search(history[-16:]):
        return 4.0  # Korean: at least / above.
    if token == '하' and history.endswith(' 이'):
        return 5.8  # The end of Korean 이하: at most / below.
    if token in {'多', '多个', '多项'} and history[-1:].isdigit():
        return 3.0
    return 0.0


def repetition(history, token):
    if any(c in token for c in '+*{'):
        text = history + token
        for m in re.finditer(r'\[([^\[\]\n]{1,60})\]([+*{])', text):
            ranges = re.findall(r'([a-zA-Z0-9])-([a-zA-Z0-9])', m[1])
            has_range = any(a.isdigit() == b.isdigit() for a, b in ranges)
            has_escape = re.search(r'\\[dDwWsSpP](?![a-zA-Z])', m[1])
            looks_like_class = bool(m[1].startswith('^') or has_range or has_escape)
            looks_like_class = (
                looks_like_class and not re.search(r'[a-zA-Z]{4,}', m[1])
            )
            if m[2] == '{' and text[m.end():].startswith('}'):
                looks_like_class = False
            if m.end() > len(history) and looks_like_class:
                value = {'*': 5.0, '+': 10.0, '{': 12.0}[m[2]]
                return value * (0.6 if '$' in token or '/' in token else 1.0)
        for m in re.finditer(r'\\+([dDwWsSpP])\\*([+*{])', text):
            if m.end() > len(history):
                if history.endswith('\\') or '/' in token:
                    return 4.5
                return 4.0 if m[1].lower() in {'s', 'p'} else 10.0
        if history.endswith('.') and token.startswith('+'):
            return 3.0
    if token.startswith(('?', ')*', ')+')) and re.search(
        r'\\[dws]|\[[^\]]*[a-zA-Z0-9]-[^\]]*\]|\.[*+]', history
    ):
        return 4.5  # Optional / lazy matching or repetition of a group.
    return 0.6 if token.startswith(('.*', '.+')) else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = -0.22 if first else quantity_ending(history, token)
    if not first and value == 0.0:
        value = repetition(history, token)
    return (doc, (history + token)[-96:]), value

programs.haiku:
"""Layer 1, MLP down-projection component 6025: an "at least / one or more" detector.

What it responds to: the word that completes a phrase about how much or how many, once the
amount has been named. Strongest is the threshold word after "or" or "and":
"two or [more]" (about 8 on average), "B- or [higher]", "$75 or [more]", "10 ppm or [less]",
"a year or [so]", "aged 5 years or [older]". Also the regex quantifier "+" that closes a
character class ("[^a-z]+", "[0-9]+": "one or more" in regex form), and the Chinese
"以上" ("or more") and "左右" ("about") after a number or unit.

The program reads only the current token and the two before it (in the same document)
and returns a strength for each rule, the typical activation for that case; anything
else is 0. The strengths are the average activations read off training text, so a
rule that is usually weak gets a small value even when a few examples are strong.
"""

READS = ()

NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
                "ten", "twenty", "thirty", "forty", "fifty", "hundred", "thousand",
                "dozen", "many", "several", "few", "some", "all", "both", "each", "most",
                "either", "any", "none"}
DIGITS = set("0123456789")
# the word after "or" (or "and"): how much it reads as a threshold ("or more", "or higher")
THRESHOLD = {"more": 8, "higher": 8, "greater": 7, "fewer": 6, "older": 6, "upwards": 6,
             "so": 6, "less": 5, "below": 5, "above": 4, "lower": 3, "up": 3,
             "something": 3, "before": 1.5, "later": 1, "under": 1, "over": 1}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    words = [_word(s) for s in prefix.token_strings]
    raw = prefix.token_strings[prefix.position].strip()
    t = prefix.position
    doc = prefix.document_ids[t]

    def back(k):
        i = t - k
        if i < 0 or prefix.document_ids[i] != doc:
            return ""
        return words[i]

    cur, p1, p2 = words[t], back(1), back(2)
    amount_before = p2 in NUMBER_WORDS or p2 in DIGITS

    if p1 == "or" and cur in THRESHOLD:
        return None, float(THRESHOLD[cur])
    if p1 == "and" and cur in THRESHOLD:
        return None, 3.0 if amount_before else 1.0
    if raw == "]+":
        return None, 9.0
    if raw == "]*":
        return None, 2.0
    if cur == "以上":
        return None, 6.0
    if cur == "以内":
        return None, 5.0
    if cur == "左右" and any(c.isdigit() for c in p1):
        return None, 5.0
    if cur in {"these", "them", "us", "you", "which", "whom"} and p1 == "of" and amount_before:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Approximate a response to indefinite amounts and brief/countable actions.

English 'some' is stronger following a verb. Chinese small-amount markers and
numeral/classifier phrases get positive values, especially action counters.
Possible verbs and classifiers come from dictionary glosses, not a parser;
ambiguous bare classifiers therefore receive conservative, selective rules.
A separate response marks 'Title:' at the beginning of a document. State and
recent-language context reset at document boundaries.
"""
from functools import lru_cache
import regex as re
import cedict
import wordnet

READS = ()
NUMERALS = '一二三四五六七八九十百千万亿两兩几幾半每各这這那某第'
QUANTITY = re.compile('([' + NUMERALS + ']+)([大小]?)(.)')
SMALL = set('点點些')
ACTIONS = set('下遍番声聲句口眼脚腳招')
OBJECTS = set('个個张張条條件套篇首颗顆块塊双雙支瓶碗杯笔筆份把匙')
EXTENTS = set('段阵陣缕縷截团團堆腔波')
OMIT_ONE = set('个個点點些下')
COUNTERS = ACTIONS | OBJECTS | EXTENTS
BRIEF_VERBS = {
    'look', 'see', 'watch', 'check', 'inspect', 'study', 'learn', 'smile',
    'laugh', 'try', 'taste', 'observe', 'appreciate', 'consider', 'think',
    'read', 'explain', 'ask', 'listen',
}
PORTION_VERBS = {
    'eat', 'drink', 'buy', 'sell', 'take', 'get', 'add', 'put', 'make', 'do',
    'bring', 'fetch', 'give', 'receive', 'acquire', 'collect', 'sprinkle',
    'pour', 'taste', 'try', 'want', 'need', 'chat', 'talk', 'write', 'reply',
    'send', 'save', 'use', 'spend', 'come',
}
QUANTIFIERS = {
    '不少': 1.3, '很多': 1.3, '许多': 1.0, '許多': 1.0, '太多': 2.5,
    '好多': 1.3, '更多': 0.3, '有些': -0.4,
    '这些': 0.5, '這些': 0.5, '那些': 0.58,
}

@lru_cache(None)
def classifier(s):
    markers = ('classifier ', 'classifier:', '(classifier ',
               '(classifier)', 'measure word ')
    return s in COUNTERS or any(g.startswith(markers) for g in cedict.glosses(s))

@lru_cache(None)
def verbs(s):
    return {g.split()[1].strip(';') for g in cedict.glosses(s)
            if g.startswith('to ')} - {'be', 'have', 'exist', 'become'}

@lru_cache(None)
def english_verb(s):
    return 'verb' in wordnet.parts_of_speech(s)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    p, previous = ('', '') if start else carry[1]
    raw = prefix.token_strings[-1]
    s = raw.strip()
    recent = ((carry[3] if not start else '') + raw)[-96:]
    header = raw == 'Title' and (start or previous == '<|endoftext|>')
    state = (doc, (previous, s), header, recent)
    if header:
        return state, 0.902
    if raw == ':' and not start and carry[2]:
        return state, -9.687
    if s.lower() == 'some':
        value = 0.05 + 0.45 * english_verb(previous)
        if previous.lower() in ('me', 'you', 'us', 'them', 'him', 'her'):
            value += 0.65 * english_verb(p)
        if previous.lower() in ('is', 'are', 'was', 'were', 'be', 'been'):
            value = 0.10
        if previous.lower() in ('with', 'into'):
            value += 0.22
        return state, value if s == 'some' else value * 0.25
    return state, chinese_value(s, previous, p, recent)


def chinese_value(s, previous, p, recent):
    if s in QUANTIFIERS:
        return QUANTIFIERS[s]
    if s in ('看看', '想想'):
        return 1.4
    if len(s) == 1 and verbs(s) and previous in ('一', '了') and p.endswith(s):
        return 2.4
    if s in ('点', '點') and previous in ('一点', '一點', '有', '还有', '還有'):
        return 2.0
    if not s:
        return 0.0

    # A numeral and classifier may be one token or two separate tokens.
    number, counter, before = '', '', ''
    m = QUANTITY.search(s)
    if m and m.end() == len(s) and classifier(m[3]):
        number, counter, before = m[1], m[3], s[:m.start()]
    elif len(s) == 1 and classifier(s):
        m = re.search('([' + NUMERALS + '0-9]+)[大小]?$', previous)
        if m:
            number, counter, before = m[1], s, previous[:m.start()]
            previous = p
        elif s in OMIT_ONE:
            counter = s
    elif len(s) == 2 and s[0] == '了' and s[1] in OMIT_ONE:
        counter, before = s[1], '了'
    if not counter:
        return 0.0
    context = before or previous
    completed = context.endswith(('了', '过', '過'))
    if completed:
        context = context[:-1] or (previous if before else p)
    verbal = bool(verbs(context) or (number and verbs(context[-2:])))
    if not number and counter in SMALL:
        verbal = bool((verbs(context) | verbs(context[-1:])) & PORTION_VERBS)
    if not number and not (verbal or completed):
        return 0.0
    if re.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', recent):
        return 0.1
    if not number and counter == '下':
        return 5.0 if verbs(context) & BRIEF_VERBS else 0.0
    if not number and counter in '点點':
        glosses = cedict.glosses(context + counter)
        if glosses and not any('little' in g or 'small amount' in g for g in glosses):
            return 0.0

    if counter in ACTIONS:
        value = 3.2
    elif counter in SMALL:
        value = 1.0 if number else 5.0
    elif counter in EXTENTS:
        value = 2.5
    elif counter in OBJECTS:
        value = 0.5 if counter in '个個' else 1.0
        value += 1.5 if not number else 0.4 * (len(s) == 1)
    else:
        value = 0.1
    if (number and number not in ('几', '幾') and not number.endswith('一')
            and not any(c in number for c in '这這那某')):
        value *= 0.45
    return value + 0.3 * bool(number and verbal) + 0.7 * completed

programs.haiku:
"""Vague-quantity words in Chinese (plus English "some").

Component: layers.1.mlp.down_proj:6027 (layer 1, MLP down projection).

What it responds to: the word that states a vague amount, or a brief bout of an action,
just before its object:
- "一下" / "了一下" ("have a look", "once"): the strongest.
- vague amounts: 一些, 一点, 很多, 许多, 不少, 太多, 多少, 有些, 些 ("some", "a bit",
  "a lot").
- "one + measure word" phrases, the measure word itself: 一句, 一张, 一波, 一丝, 一眼 ...
  (strong); a bare measure word such as 个, 件, 条, 张, 点 (weaker).
- English " some" (weak).
Its strength is higher when the word follows 了 or 一 ("了一下", "的一点") and when it
sits in Chinese text; after digits or Latin text it is weak. Bare 下 ("down", "next") is
not a quantity, so it stays at 0 unless it follows 了 or 一.

One exact artifact: a colon right after "Title" at the start of a document (the tokens
"<|endoftext|>", "Title", ":") is strongly negative, about -9.7.

This is a hand-written approximation: it reads the current and previous token's text and
gives each word class a value fitted by hand to the component's mean activation. It does
not run the model.
"""

import regex

READS = ()

ONE_DOWN = {"一下", "了一下"}
VAGUE = {"一些", "一点", "很多", "许多", "不少", "太多", "多少", "好多", "有些", "些", "點"}
MEASURE = set("件条张句点點片份套段杯支口块次场波把声眼番阵所丝抹股笔座篇遍趟层批碗圈脚半盅")
# measure words that carry activation on their own (a bare 把 or 波 does not)
BARE_MEASURE = set("件条张句点點份套段杯场阵个些")


def _word_value(word):
    """Value of a word's class before context: its typical activation."""
    if word in ONE_DOWN:
        return 3.0
    if word in VAGUE:
        return 1.5
    if word == "一个":
        return 0.5
    if len(word) >= 2 and word[0] == "一" and all(c in MEASURE for c in word[1:]):
        return 1.8
    if len(word) >= 3 and word.startswith("了一") and all(c in MEASURE for c in word[2:]):
        return 1.8
    if word in BARE_MEASURE:
        return 0.6
    if word == " some":
        return 0.25
    return 0.0


def _is_cjk(word):
    return bool(word) and bool(regex.search(r"\p{Script=Han}", word))


def _after_yi_or_le(word):
    return word.endswith("一") or word.endswith("了")


def step(carry, prefix, upstream):
    s = prefix.token_strings
    word = s[-1]
    before = s[-2] if len(s) > 1 else ""
    if word == ":" and before == "Title" and len(s) > 2 and s[-3] == "<|endoftext|>":
        return carry, -9.7
    value = _word_value(word)
    if word == " some":
        return carry, value
    if value == 0 and before == "一" and _is_cjk(word):
        # a Chinese character right after the numeral 一 starts a "one X" amount or brief action
        return carry, 0.6
    if value > 0 and _after_yi_or_le(before):
        value += 1.5
    if value > 0 and not _is_cjk(before):
        value *= 0.3
    return carry, float(value)

programs.sol:
"""A negative response to geographic qualifiers, e.g. 'Denver, Colorado'.

Use ISO place names and postal codes, plus dictionary city names. A country
or state following a comma is strongest when it follows another place name.
Recognized country lists are suppressed; multi-word country/state qualifiers
are weakened. Non-letter tokens briefly echo a place response, especially
spaces/ZIP digits after postal codes. Small name-suffix and region-prefix
responses are included too.
This is a category-level approximation, not a separate weight for each name.
"""
import re
import unicodedata
from functools import lru_cache
import pycountry
import wordnet

READS = ()


def normal(text):
    text = unicodedata.normalize('NFKD', text).casefold()
    text = ''.join(c for c in text if not unicodedata.combining(c))
    return ' '.join(re.findall('[a-z]+', text))


NAMES = {}
for region in pycountry.subdivisions:
    group = {'US': 'state', 'CA': 'province', 'AU': 'province',
             'GB': 'british'}.get(region.country_code)
    if group:
        NAMES[normal(region.name.split(',')[0].split('[')[0])] = group
for country in pycountry.countries:
    for field in ('name', 'common_name', 'official_name'):
        name = getattr(country, field, '').split(',')[0]
        if name:
            NAMES[normal(name)] = 'country'
# Common English alternatives and national initialisms.
for name in ('Russia', 'Britain', 'Turkey', 'Vietnam', 'North Korea',
             'South Korea', 'England', 'Scotland', 'Wales', 'Northern Ireland',
             'US', 'USA', 'UK', 'UAE'):
    NAMES[normal(name)] = 'country'
for region in pycountry.subdivisions.get(country_code='US'):
    NAMES[normal(region.name)] = 'state'
CODES = {r.code.split('-')[1] for r in pycountry.subdivisions
         if r.country_code in {'US', 'CA', 'AU'}}
# Traditional printed state/province abbreviations, rather than postal codes.
SHORT = set(('Ala Ariz Ark Calif Colo Conn Del Fla Ill Ind Kan Ky La Mass '
             'Mich Minn Miss Mo Mont Neb Nev Okla Ore Pa Tenn Tex Va Vt '
             'Wash Wis Wyo Ont Que').lower().split())
LEADS = {n.split()[0] for n, k in NAMES.items()
         if k in {'state', 'province'} and ' ' in n}
WORDS = re.compile(r'[A-Za-zÀ-ž]+(?:[-\'’][A-Za-zÀ-ž]+)*')
COMMA = re.compile(r', +(?:the +)?$')

# Ordinary mention, comma increment, capitalized-predecessor increment.
RESPONSE = {
    'country': (-0.159, -3.499, -4.470),
    'state': (-0.374, -3.049, -5.021),
    'province': (-0.336, -1.112, -2.244),
    'british': (-0.047, -0.518, -1.005),
    'code': (0.014, -0.658, -7.911),
    'short': (-0.022, -1.981, -2.562),
}
SCALE = 0.8


def place(text):
    for word in list(WORDS.finditer(text))[-5:]:
        name = normal(text[word.start():])
        if name in NAMES:
            return NAMES[name], word.start(), name
    return '', len(text), ''


@lru_cache(maxsize=8192)
def city_at_end(text):
    words = list(WORDS.finditer(text))[-3:]
    return any(wordnet.is_a(text[w.start():], 'city') for w in words)


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False)
    _, tail, old_kind, old_comma = carry
    text = (tail + token)[-160:]
    value = 0.002
    letters = any(c.isalpha() for c in token)
    kind, start, name = '', len(text), ''
    if letters:
        kind, start, name = place(text)
        code = re.search(r'(?<![A-Za-z])([A-Z](?:\.?[A-Z]){1,2})\.?$', text)
        if code and code[1].replace('.', '') in CODES:
            kind, start, name = 'code', code.start(1), code[1]
        if not kind:
            last = list(WORDS.finditer(text))
            if last and normal(last[-1][0]) in SHORT and last[-1][0].istitle():
                kind, start, name = 'short', last[-1].start(), last[-1][0]
    before = text[:start]
    comma = bool(COMMA.search(before))
    left = COMMA.sub('', before).rstrip()
    last = re.search(r'([A-Za-z]+)$', left)
    proper = bool(last and (last[1].istitle() or last[1] in CODES))
    previous_kind = place(left)[0] if comma else ''
    if kind == 'country' and comma:
        continent = bool(last and last[1].lower() in {
            'europe', 'asia', 'africa', 'america', 'antarctica', 'oceania'})
        if previous_kind == 'country' or continent:
            comma = False
    if kind:
        base, comma_extra, name_extra = RESPONSE[kind]
        value += base + comma * comma_extra + (comma and proper) * name_extra
        if comma:
            parent = kind == 'country' and previous_kind in {'state', 'province'}
            if city_at_end(left) or parent:
                value -= 3.642
        if ' ' in name:
            value -= 0.024
            if comma and kind in {'state', 'country'}:
                value += 5.386
        if kind == 'code' and not comma:
            if re.search(r'[A-Z][a-z]+ +$', before):
                value -= 0.965
    elif letters:
        last_word = list(WORDS.finditer(text))
        if last_word:
            word = last_word[-1][0]
            if COMMA.search(text[:last_word[-1].start()]) and normal(word) in LEADS:
                value -= 0.542
            if word in {'Sr', 'Jr', 'Inc', 'Ltd'}:
                value -= 0.234
                if re.search(r', *$', tail):
                    value -= 1.403
    if old_kind:
        if not letters:
            value -= 0.163
            if old_comma:
                value -= 1.766
                if ',' in token:
                    value -= 1.431
                if old_kind == 'code':
                    if token.isspace() and '\n' not in token:
                        value -= 7.219
