"""A short, exposed 'de' spelling detector.

Look for de (also transliterated or accented) inside a short token, or
across a d/e token boundary. Common grammatical de-words and inflectional
endings are weaker; uncommon e-fragments after d are stronger. Some
signal carries to a short following fragment, especially in capitals.
A capitalized preceding fragment strengthens spaced lower-case de.
Long words containing the same letters receive only a small response.
"""
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
GRAMMATICAL = {'de', 'des', 'del', 'dem', 'den', 'der', 'det'}


@lru_cache(maxsize=8192)
def romanize(text):
    # Exclude Han transliterations and the Japanese grammatical particle de.
    if text.strip() == 'で':
        return ''
    if any('CJK' in unicodedata.name(c, '') for c in text):
        return ''
    return anyascii(text)


def response(raw, previous):
    translated = romanize(raw)
    s = translated.strip().lower()
    old = romanize(previous).lower()
    continuation = bool(translated) and not translated[0].isspace()
    n = len(s)
    if not n:
        return 0.0

    if continuation and old.endswith('d') and s.startswith('e'):
        value = (1.1, 1.0, 0.65, 0.15)[min(n, 4) - 1]
        if n == 2:
            rarity = max(0.0, min(3.0, 5.0 - zipf_frequency(s, 'en')))
            value += 1.85 * rarity
            if s in {'ed', 'er', 'en'}:  # familiar inflectional endings
                value = 0.5
        if translated != raw:
            value += 1.2 if n == 1 else 0.5
        return value

    if 'de' in s:
        at = s.index('de')
        if at == 0:
            value = {2: 1.1, 3: 1.25, 4: 0.25}.get(n, 0.1)
            if n <= 3:
