                    if raw == translated and s in GRAMMATICAL:
                        value -= 0.8
                        if s == 'de' and previous.strip()[:1].isupper():
                            value += 0.7
                if n == 3 and s[-1] in 'lmnr':
                    value -= 0.4
                if s == 'def':  # programming's function-definition keyword
                    value -= 0.3
            return value
        if at == 1 and not s[0].isalpha() and n <= 4:
            return 1.7 if n == 3 else 1.2
        value = {3: 0.8, 4: 0.35}.get(n, 0.04)
        if n == 4 and not continuation:
            value -= 0.3
        return value

    if continuation and translated[0].isalpha() and old.endswith('de'):
        short_source = len(old.strip()) <= 3
        value = (1.1, 0.15, 0.3, 0.1)[min(n, 4) - 1]
        if short_source and n <= 2:
            value += 1.2 if n == 1 else 0.7
        if n <= 2 and previous.strip().isupper() and raw.strip().isupper():
            value += 1.3
        return value
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    raw = prefix.token_strings[-1]
    return (document, raw), float(response(raw, previous))

"""A small detector for text-formatting and document-boundary signals.

It recognizes chat/thinking delimiters, an anonymized email's surname field,
URL separators, and punctuation. Joining punctuation to Chinese or Japanese
