or ellipses. At document starts a coarse character-class baseline replaces
these ordinary-context rules. No token-number lookup table is used.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Han}')
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, recent = '', b''
    else:
        _, previous, recent = carry
    before = recent.decode('utf-8', errors='ignore')
    han = bool(HAN.search(before[-1:]))
    kana = bool(KANA.search(before[-1:]))
    spaced = text.startswith(' ')
    mark = text.strip()
    value = 0.0

    if text == '.lastname' and before.endswith('firstname'):
        value = 2.0
    elif text == '<think>':
        value = 0.13
    elif text == '</think>':
        value = 0.025
    elif text == '</tool_response>':
        value = 0.09
    elif text == '<|im_start|>':
        value = 0.015
    elif text == '\n\n':
        value = -0.278 if previous == '</think>' else (
            -0.065 if previous == '<think>' else -0.01)
    elif text == '\n\n\n':
        value = 0.5 if han else 0.18 if kana else -0.07
    elif mark == '://':
        value = -0.14
    elif mark == '—':
        # A dash run can continue across a line break or another dash.
        joined_to = before.rstrip()
        if previous == '——':
            joined_to = joined_to.rstrip('—')
        joined_to = joined_to[-1:]
        if HAN.search(joined_to):
            value = -0.75 if spaced else -2.1
        elif KANA.search(joined_to):
            value = -0.35
        else:
            value = 0.15
    elif mark == '-':
        if han or kana:
            value = 0.32 if spaced else -0.43 if han else -0.15
        else:
            if spaced:
                value = -0.07
            else:
                value = 0.01 if previous.strip().isdigit() else 0.025
    elif mark and set(mark) <= {'.', '…'}:
        dots = mark.count('.') + 3 * mark.count('…')
        if dots >= 3:
            if han:
                value = -0.93 if '…' in mark else -0.25 * (dots - 2)
                value = max(-2.0, value)
            elif kana:
                value = -0.37 if '…' in mark else -0.13 * (dots - 2)
            else:
                if spaced:
                    value = 0.09 if '…' in mark else 0.02
                else:
                    value = 0.22 if '…' in mark else min(0.2, dots * 0.03)
    elif mark and set(mark) == {'·'} and len(mark) >= 2:
        value = -0.7 if previous.strip().endswith('·') or first else 0.0
    elif text in ('import', 'using'):
        if previous.rstrip().endswith(';'):
            value = 0.105 if text == 'import' else -0.23
        elif previous.endswith('\n'):
            value = -0.055
    elif text == 'namespace' and previous.isspace():
        value = -0.75

    if first:
        if text == '<|im_start|>':
            value = -0.226
        elif mark.isdecimal():
            value = 0.23
        elif mark.isalpha():
            value = 0.14 if not (spaced and mark.istitle()) else 0.0
        elif text == '\n':
            value = 0.446
        elif text == '\n\n':
            value = 0.263
        elif text == '\t':
            value = -0.4
        elif text == '#':
            value = 0.405
    recent = (recent + prefix.token_bytes[-1])[-128:]
    return (doc, text, recent), value

