"""Candidate v3: concept rules for layers.1.mlp.down_proj:6034.

The component is mostly diffuse: its activation has RMS 0.045 and no single concept
explains most of it. These rules capture the consistent, nameable cases:
  - first token of a document (no context): code-like identifiers go negative, prose-like
    tokens go slightly positive;
  - dashes and ellipses (— … ...) are mildly positive; a spaced hyphen " -" is mildly negative;
  - the blank line that closes a thinking block ("</think>" then "\\n\\n") is negative;
  - the anonymised email placeholder "firstname.lastname" is strongly positive.
"""
import re

READS = ()

DASHES_ELLIPSES = {"—", " —", "——", " ——", "…", "….", "...", "...."}
THINK_TAGS = {"<think>", "</think>", "</tool_response>"}
CODE_LIKE = re.compile(r"[_{}()\[\];#=<>\\*/]|[a-z][A-Z]")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.25 if CODE_LIKE.search(tok) else 0.12
    if tok == ".lastname" and prev == "firstname":
        return carry, 1.8
    if tok == "\n\n" and prev == "</think>":
        return carry, -0.27
    if tok in DASHES_ELLIPSES:
        return carry, 0.14
    if tok == " -":
        return carry, -0.07
    if tok in THINK_TAGS:
        return carry, 0.085
    if tok == "://":
        return carry, -0.14
    return carry, 0.0

programs.sol:
"""A sparse approximation for guillemets and web-page formatting.

Double left guillemets («) after whitespace or at document start are positive.
Word frequencies estimate surrounding language; repetitions attenuate the
response, while forum-header context increases it.
Local rules cover URL paths, profile/author labels, comment attributions,
navigation, omissions, and middle-dot leaders. Other tokens predict zero.
This keeps recognizable formatting cases, not the remaining lexical responses.
"""
import re
from wordfreq import zipf_frequency

READS = ()

# First opening quote, before accounting for repetition.
QUOTE_HEIGHT = {
    "en": 3.8,
    "fr": 1.9,
    "de": 4.0,
    "it": 1.25,
    "ru": 0.5,
    "es": 1.8,
    "pt": 2.0,
    "ar": 0.9,
    "fa": 0.9,
    "el": 1.1,
}
VIDEO_PATH_HEIGHT = {
    "/user": -3.0,
    "/channel": -0.7,
    "?v": -1.8,
}
FORUM = re.compile(r"Posts:|Respect:|Likes Given:|#{2,}\s*Re:")


def quote_value(before, count, forum):
    if forum and (not before or before.endswith("\n")):
        return 7.6 / (1.0 + 0.15 * count)
    words = re.findall(r"[^\W\d_]+", before)[-40:]
    if not words:
        return 1.0
    language = max(
        QUOTE_HEIGHT,
        key=lambda lang: sum(zipf_frequency(w, lang) for w in words),
    )
    height = QUOTE_HEIGHT[language]
    rate = 1.0 if language == "ru" else 0.25
    return height / (1.0 + rate * count)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before, quotes, forum = "", 0, False
    else:
        _, before, quotes, forum = carry
    token = prefix.token_strings[-1]
    text = (before + token)[-700:]
    forum = forum or bool(FORUM.search(text))
    value = 0.0

    opening_quote = token.strip() == "«" and (
        token[0].isspace() or not before or before[-1].isspace()
    )
    if opening_quote:
        value = quote_value(before, quotes, forum)
    elif token and set(token) == {"·"} and len(token) >= 2:
        value = -2.0
    elif token == "\xa0":
        value = -1.3 if before.rstrip().endswith("–") else 0.06
    elif token == "/~" and re.search(r"(?:https?://|www\.)\S+$", before):
        value = -4.4
    elif token == "/wiki" and "wikipedia.org" in before[-100:]:
        value = -2.8
    elif token in VIDEO_PATH_HEIGHT and "youtube.com" in before[-100:]:
        value = VIDEO_PATH_HEIGHT[token]
    elif token == "/math" and before.endswith("khanacademy.org"):
        value = -4.2
    elif token == "/env" and before.endswith("/bin"):
        value = 1.0
    elif token == "Joined" and (not before or before.endswith("\n")):
        value = -0.45
    elif token == " by" and re.search(
        r"(?:^|[\n|])(?:Originally Posted|[Pp]osted|Last edited|[Ee]dited)$",
        before,
    ):
        value = 0.5
    elif token == " reading" and before.endswith("Continue"):
        value = 0.75
    elif token == " (@" and re.search(r"(?:^|\n)—[^\n]*$", before):
        value = -1.1
    elif token == " on" and before.endswith("##### Share"):
        value = 0.6
    elif token == " sites" and before.endswith("Share on other"):
        value = -1.35
    elif token == " Page" and re.search(r"posts\s*[•|]\s*$", before):
        value = 1.1
    elif token == "_\n" and before.endswith("___"):
        value = 1.3
    elif token == " Reply" and before.endswith("«"):
        value = -1.1
    elif "…" in token and "[" in token:
        value = 1.3
    elif token.strip() == "[...]":
        value = 1.0
    elif token == '="_' and before.endswith("target"):
        value = -1.05

    return (document, text, quotes + int(opening_quote), forum), value

programs.haiku:
"""Guillemet quotes («), the repeated middle-dot run (··) and the '/wiki' URL path segment.

- An opening guillemet « in Latin-script text (French, English, Norwegian, ...) is a strong
  positive activation, about +2 on average (large when it opens a quoted title or name).
  In Cyrillic (Russian) text it is almost silent, so it gets a small value.
- The middle-dot token ·· gives a constant -2.
- '/wiki' (as in en.wikipedia.org/wiki/...) gives -2.8.
- Everything else is predicted as 0.
"""

READS = ()

CYRILLIC = range(0x0400, 0x0500)


def _is_cyrillic(text):
    return any(ord(ch) in CYRILLIC for ch in text)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in (" «", "«"):
        recent = "".join(prefix.token_strings[-30:-1])
        return None, (0.3 if _is_cyrillic(recent) else 2.2)
    if tok == "··":
        return None, -2.0
    if tok == "/wiki":
        return None, -2.8
    return None, 0.0

programs.sol:
"""A partial, cue-based approximation of conversational activation spikes.
Recognize English personal questions, speaker labels, affirmative replies,
opinion/quantity phrases, and Japanese polite endings. Recent sentence and
line context distinguish questions from generic directives. Reset at document
boundaries; leave unmodelled token-specific offsets at zero.
"""
import re

READS = ()
WH = set('what why how when where who which whom'.split())
AUX = set(('do did does can could would will should have has had '
           'are were is was').split())
FIRST = {'i', 'we', 'my', 'our'}
PREP = {'for', 'to', 'with', 'about', 'from'}
STARTERS = set('and so but at in from on then now well'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 10000, 10000)
    _, previous, sentence, line, qage, iage = carry
    qage, iage = qage + 1, iage + 1
    token = prefix.token_strings[-1]
    w, p = token.strip().lower(), previous.strip().lower()
    words = re.findall(r'[a-z]+', sentence.lower())
    recent = set(words[-16:])
    lead = re.findall(r'[a-z]+', sentence.lower().rsplit(':', 1)[-1])
    first = lead[0] if lead else ''
    wh = first in WH or (first in STARTERS and bool(set(lead[:6]) & WH))
    question = wh or first in AUX
    personal = bool(recent & {'you', 'your'})
    after_answer = iage < 120 and not (recent & FIRST)
    qmark = '?' in token and all(ch in '? !\n\r\\' for ch in token)
    value = 0.0

    if w == 'you':
        if p == 'did':
            value = 4.0
        elif p in {'do', 'does'}:
            value = 2.75 if question else 1.4
        elif question and p in {'would', 'were'} | PREP:
            value = 3.0
        elif p in AUX:
            value = 0.8
        elif p in {'help', 'thank'}:
            value = -0.3
        else:
            value = 0.6 if question else 0.1
    elif w == 'your':
        if wh:
            copula = p in {'is', 'was', 'are', 'were', "'s", '’s', 'has'}
            value = 4.8 if copula else (1.7 if qage < 150 else 0.2)
        else:
            value = 0.08 if p in PREP else -0.1
    elif qmark:
        newline = '\n' in token or '\\' in token
        if personal and newline:
            value = 3.5 if question and after_answer else 1.8
            if '\n\n' in token:
                value *= 0.4
        elif personal:
            value = 0.6
        else:
            value = 0.6 if newline and '\n\n' not in token else 0.0
    elif w in {':', '：', ':**', ']:'}:
        label = line.strip().strip('*#[] ')
        parts = re.findall(r'[^\W\d_]+', label)
        name = (0 < len(parts) <= 5 and len(label) < 65 and
                all(x[0].isupper() or len(x) == 1 for x in parts))
        if name and qage < 20:
            value = 3.9 if label.isupper() and len(label) > 1 else 1.5
        elif label.lower() in {'q', 'question', 'interviewer'}:
            value = 1.0
    elif w in {'think', 'believe'} and p in {'i', 'we', 'you', 'he', 'she', 'they'}:
        value = 0.7
    elif w in {'favorite', 'favourite'}:
        value = 1.0
    elif w in {'yes', 'yeah', 'yep'}:
        value = 0.7 if w == 'yes' else 2.0
        if p in {':', '：'}:
            value += 0.5
    elif w == 'of' and p == 'some':
        value = 0.85
    elif w == 'of' and previous.strip() == 'One':
        value = 0.5
    elif w == 'lot' and p == 'a':
        value = 0.5
    elif w.endswith(('ました', 'でした')) or w in {'んです', 'ですか'}:
        value = 1.5

    if w in FIRST:
        iage = 0
    if qmark:
        qage = 0
    sentence = (sentence + token)[-350:]
    if re.search(r'[.!?]\s*$', token) or '\n\n' in token:
        sentence = ''
    line = (line + token).split('\n')[-1][-350:]
    return (doc, token, sentence, line, qage, iage), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 6036: a "direct question to you" detector.

What it responds to, in plain terms:
  * the word "you" (and "your") when it is the subject of a question: "do you", "Can you",
    "Are you", "what you", "how you" (strongest right after "do");
  * the verb of thought or feeling that follows such a "you" ("do you [feel]",
    "do you [believe]", "makes you [think]");
  * a speaker label's colon in a dialogue or interview: "Luigi:", "Professor e:";
  * question marks ending a question, and a few answer words ("Yes", "Yeah") that open a reply.

It is mostly silent: almost every token gets 0. Values are rough average activations for each
case, read off the component's activations on training rows; they are not fitted per token.

Carry: whether the current clause is a question (a question word appeared since the last
sentence break), how many tokens since the last "you", and the current line's text so far (to
spot speaker labels). All reset at each new document.
"""

READS = ()

QUESTION_WORDS = {
    "what", "how", "why", "where", "when", "who", "which",
    "do", "does", "did", "can", "could", "are", "is", "will", "would", "should",
}
AUX_BEFORE_YOU = {"do", "does", "did", "can", "could", "are", "will", "would", "what", "how", "why"}
YOU_WORDS = {"you", "your", "yours", "yourself", "you're", "you’re", "you'll", "you’ll", "you've", "you’ve"}
THOUGHT_VERBS = {
    "think", "believe", "feel", "know", "see", "say", "says", "said", "makes", "like",
    "want", "wanted", "decided", "favorite", "lot", "interests", "enjoy",
}
