def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "question": False, "since_you": 99, "prev": "", "line": ""}

    # Speaker label: a colon after a short, capitalised line such as "Luigi:".
    label = (
        word == ":"
        and 0 < len(carry["line"].strip()) <= 25
        and carry["line"].strip()[:1].isupper()
        and len(carry["line"].split()) <= 3
    )
    is_you = word in YOU_WORDS
    value = 0.0
    if is_you:
        if carry["prev"] in AUX_BEFORE_YOU:
            value = 0.6          # "do you", "Can you", "what you": the subject of a question
        elif carry["question"]:
            value = 0.2
        else:
            value = 0.05
    elif label:
        value = 0.2
    elif "?" in token:
        value = 0.15
    elif word in THOUGHT_VERBS and carry["question"] and carry["since_you"] <= 2:
        value = 0.4              # "do you [feel]", "makes you [think]"
    elif word in AFFIRMATIONS:
        value = 0.1

    # Update the state for the next token.
    if word in QUESTION_WORDS:
        carry["question"] = True
    if is_you:
        carry["since_you"] = 0
    else:
        carry["since_you"] = min(carry["since_you"] + 1, 99)
    if "\n" in token or token.strip() in {".", "!", "?"}:
        carry["question"] = False
        carry["line"] = ""
    else:
        carry["line"] += token
    if "\n" in token:
        carry["line"] = ""
    carry["prev"] = word
    return carry, float(value)

