"""Detect source-file headers, not executable statements.

Package/namespace boundaries and C# using-directive endings receive large
negative predictions. Header documentation and file-opening markers have
separate values. Only the current and previous nonempty lines are retained;
ordinary prose and program bodies otherwise predict zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, True)
    _, line, previous, csharp, fresh = carry
    if token in ('<|endoftext|>', '<|im_start|>'):
        return (doc, '', '', False, True), 0.0

    # Normalize source quoted in JSON, and source listings with line numbers.
    whole = (line + token).replace('\r', '')
    whole = whole.replace('\\r', '').replace('\\n', '\n')
    start = whole.lstrip()
    numbered = bool(re.match(r'\d+\t', start))
    start = re.sub(r'^\d+\t\s*', '', start)
    start = re.split(r'["\']', start)[-1].lstrip()
    value = 0.0
    if token.strip() == 'namespace':
        value = -11.9 if csharp else (-2.4 if fresh else 0.0)
    if fresh and token == 'package':
        value = 3.25

    if ';' in token:
        if re.match(r'package\s+[\w.]+', start):
            value = -12.55 if token.count('\n') >= 2 else -10.55
            if numbered:
                value = -10.3
        elif re.match(r'namespace\s+[\w\\]+', start):
            value = -7.8
        elif re.match(r'using\s+namespace\b', start):
            value = -1.7
        elif re.match(r'using\s+[\w.]+\s*;', start):
            csharp = True
            value = -3.8 if start.startswith('using System') else -6.1
        elif re.match(r'import\s+[\w.]+', start):
            value = -2.45 if '*' in token else -0.2
            if '\\' in token:
                value = -1.2

    namespace_scope = csharp or bool(re.match(r'namespace\s+[A-Z]', start))
    if '\n' in whole:
        if re.match(r'package\s+[\w.]+\s*\n', start):
            value = -6.15 if token.count('\n') >= 2 else -0.4
        if re.match(r'namespace\s+[\w.]+\s*\n', start):
            value = -5.25 if namespace_scope else -0.65
    opens_namespace = start.startswith('namespace ')
    opens_namespace |= not line.strip() and previous.startswith('namespace ')
    if '{' in token and opens_namespace:
        value = -4.6 if namespace_scope else -1.3

    if token.strip() == '/**':
        value = 0.3
        if previous.startswith(('import ', 'use ')):
            value = -7.1 if '\n' in token else -4.2
        if previous.startswith('package '):
            value = -9.6
        if fresh:
            value = 2.35
    if token.strip() == '///' and csharp:
        indent = len(whole) - len(whole.lstrip(' '))
        value = -4.25 if indent <= 4 else 0.0
    if fresh and token.strip() == '//' and '\n' in token:
        value = -18.0
    if fresh and token == '\r':
        value = -13.05

    if '\n' in whole:
        parts = whole.split('\n')
        previous = next((s.strip() for s in reversed(parts[:-1])
                         if s.strip()), previous)
        previous = re.sub(r'^\d+\t\s*', '', previous)
        line = parts[-1]
    else:
        line = whole[-400:]
    return (doc, line, previous, csharp, fresh and token == '\r'), value

"""Partial surface explanation: title labels, tag controls, and i-rich spelling.

The colon in a document-initial `Title:` is strongly negative. `Show Tags`
is positive, more so beside a permalink. A small background signal counts
normalized i-like letters in words and identifiers, favoring i-dense
spellings uncommon in English. Document starts and explicit formatting markers have
separate rules. Much token-specific variation remains unexplained.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
I_LETTERS = frozenset('iιиіı')
DETERMINERS = {'The', 'This', 'That', 'These', 'Those', 'A', 'An'}
IMPORTS = {'import', 'from', 'package'}
FORMATTING = {
    '</tool_call>': 0.107,
    '</think>': -0.09,
    '··': -0.45,                  # doubled middle-dot separator
    '_{': 0.095,                 # braced mathematical subscript
}


@lru_cache(maxsize=32768)
def spelling(word):
    text = unicodedata.normalize('NFD', word.lower())
    count = sum(ch in I_LETTERS for ch in text)
    length = max(1, sum(ch.isalpha() for ch in word))
    return count, count / length


def initial_value(token, word, density):
    if token == 'Title':
        return -0.43
    if token in DETERMINERS:
        return -0.36
    if token in IMPORTS:
        return -0.81
    if len(token) == 1 and token.isascii() and token.isupper():
        return 0.30
    if token == '#':
        return -0.41
    if token == '"':
        return -0.84
    if token in ('"""\n', "'''\n"):
        return -1.59
    if token in (' (', ' ['):
        return 1.09 if token == ' (' else 0.99
    if token == '--':
        return 1.39
    if token and not token.strip() and '\n' in token:
        return 0.12 if token.count('\n') == 1 else 0.40
    if density >= 0.2:
        return 0.22 if zipf_frequency(word.lower(), 'en') < 4 else 0.03
    if (word.isascii() and word.islower() and word.isalpha()
            and len(word) >= 3 and zipf_frequency(word, 'en') < 1.75):
        return 0.16
    return -0.11


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, word = 0, '', ''
    else:
        _, position, previous, word = carry
    # Keep spelling across token boundaries, including compound identifiers.
    for ch in token:
        word = word + ch if ch.isalpha() or (ch in '._-' and word) else ''
    word = word[-80:]
    count, density = spelling(word)
    previous_i, _ = spelling(previous)
    value = 0.006 if previous_i else 0.0
    if count >= 2:
        value = 0.025
        if density > 0.25 and zipf_frequency(word.lower(), 'en') < 4:
            value = 0.12 if previous_i else 0.07
    if position == 0:
        value = initial_value(token, word, density)
    elif position == 1 and previous == 'Title' and token == ':':
        value = -5.05
    elif previous.strip() == 'Show' and token == ' Tags':
        recent = ''.join(prefix.token_strings[-min(position + 1, 7):])
        value = 0.83 if 'permalink' in recent else 0.61
    elif token in FORMATTING:
        value = FORMATTING[token]
    return (doc, position + 1, token, word), value

