READS = ()
OPEN_BRACKET = {" (", " [", " {"}
CODE_OR_HEADER = {
    "import", "package", "from", "#", "/*\n", "/**\n", '"""\n', "---\n", "//\n", '"',
    "\\n", "\\t", "Int", "int", "char", "class",
}
SENTENCE_OPENER = {"The", "This", "When", "My", "On", "By", "As", "What", "Person", "La", "It"}
MID_SENTENCE = {" to", " with", " for", " using", "using", " the", "\n\n", "I", "M", "P", "D", "C", "O"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    first_in_doc = prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if not first_in_doc:
        if tok.startswith("··") and set(tok) == {"·"}:
            return carry, -0.45
        if tok == " Tags" and prefix.token_strings[-2] == "Show":
            return carry, 0.6
        return carry, 0.0
    if tok in OPEN_BRACKET:
        return carry, 1.0
    if tok in CODE_OR_HEADER:
        return carry, -0.9
    if tok in SENTENCE_OPENER:
        return carry, -0.5
    if tok in MID_SENTENCE:
        return carry, 0.3
    return carry, -0.1

programs.sol:
"""Approximate a document-initial pulse with lexical and orthographic modulation.

Only the first token of a document (including a cropped row) gets a pulse.
Digits, heading markers, declarations and some scripts get positive pulses.
English continuations, pronouns and abstract-noun endings get smaller ones.
Whitespace, punctuation and import/export keywords have separate defaults.
These are broad averages; individual first tokens vary substantially.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
PRONOUNS = set(
    'i me my mine we us our you your he him his she her '
    'it its they them their'.split()
)
DETERMINERS = set(
    'the a an this that these those some any each every all both'.split()
)
DECLARATIONS = set('def function class namespace package'.split())
PRIMITIVE_TYPES = set(
    'int char void float double bool boolean byte long short'.split()
)
AUXILIARIES = set(
    'is am are was were be been being do does did have has had '
    'can could may might must shall should will would'.split()
)


def initial_value(token):
    text = token.strip()
    if token.startswith('<|'):
        return 3.0 if token == '<|im_start|>' else 0.0
    if not text:
        if '\n' in token:
            return -0.7
        if '\t' in token:
            return -0.5
        return 0.03 if len(token) == 1 else 2.2
    if len(token) == 1 and token in '0123456789':
        # The initial pulse varies with the numeral, not its value in context.
        return (-0.18, 2.74, 1.93, 3.69, 4.01,
                4.07, 4.36, 4.24, 3.16, 2.38)[int(token)]
    space = token.startswith(' ')
    if token in {'import', 'export'}:
        return -2.0
    if text in DECLARATIONS or text in PRIMITIVE_TYPES:
        return 1.5 if space else 4.5
    if not text.isalpha():
        if token == '#':
            return 4.0
        if token == '.':
            return 2.23
        value = 0.3 - 0.7 * space
        if '\n' in token:
            value -= 1.4
        if '"' in text or "'" in text:
            value -= 0.6
        if text in '()[]{}':
            value -= 0.7
        return value
    if not text.isascii():
        if regex.search(r'\p{Script=Cyrillic}', text):
            value = 3.6
        elif regex.search(r'\p{Script=Han}', text):
            value = 2.5
        else:
            value = 1.0
        return value - 0.5 * space
    word = text.lower()
    value = 1.8 - 1.4 * space
    value -= 0.07 * (min(len(word), 12) - 4)
    frequency = zipf_frequency(word, 'en')
    value -= 0.4 * max(0.0, frequency - 5.0)
    if frequency < 1.0:
        value -= 0.8
    if len(word) == 2:
        value -= 0.6
    if word in PRONOUNS:
        value -= 1.5 - 1.1 * space
    if word == 'a':
        return -0.3 if space else 2.9
    if word in DETERMINERS:
        value -= 0.6 - 0.4 * space
    if word in AUXILIARIES:
        value -= 0.25 + 0.75 * space
    if word.endswith(('tion', 'ment', 'ness', 'ity')):
        value -= 1.5
    if word.endswith('ing') and len(word) > 4:
        value += 0.7
    return value


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = initial_value(prefix.token_strings[-1]) if first else 0.0
    return None, value

programs.haiku:
"""Layer-1 MLP down-projection component 6041: a document-start feature.

What it does, in plain terms
----------------------------
This component is almost silent except at the first token of each document (in a
packed row, the token right after a document boundary, or the first token of a row).
There it writes a token-dependent value into the residual stream: positive for
digits, '#' and other hash/comment markers, non-Latin scripts, chat-turn markers,
programming words and imperative verbs ("make", "break", "test", "How", "Making");
negative for line-ending and closing-bracket tokens, end-of-text, catalogue/record
nouns ("Card", "Product", "Event", "Content"), and for stop words that continue a
sentence with a leading space (" the", " of", " is", " that").
Mid-document tokens get 0, except the dot-leader token '··', which is about -1.5 everywhere.

The value is a property of the token alone (the model has no earlier context at a
document start), so a word list is the natural description. Ordinary capitalised or
lower-case words are mildly positive.

Predictions are scored with the token alone, as the component sees them at a document start.
"""

READS = ()

CHAT_START = "<|im_start|>"
END_OF_TEXT = "<|endoftext|>"
CLOSERS = {")", "]", "}", "});", "},", "}}", ")}", "),", '",', '";', '"', "'", "```"}
STOP_WORDS = set(
    "the of and to a in is that for it as on with by at from or be are was were this "
    "an not have has can if which we they he i you his her their its but so will one "
    "all more about into than then there when what who how also".split()
)
CATALOG_NOUNS = set(
    "card cart product item book order event document content song project company "
    "course unit app title person trip job plan account activity variable param station".split()
)
PROGRAMMING_OR_IMPERATIVE = set(
    "make break char void state test command name function class main list number string "
    "check print return package include define hello help echo".split()
)


def is_non_latin(text):
    """Cyrillic or CJK characters."""
    return any("Ѐ" <= c <= "ӿ" or "一" <= c <= "鿿" for c in text)


def start_value(token):
    """The component's activation when `token` is the first token of a document."""
    word = token.strip().lower()
    if token == CHAT_START:
        return 3.0
    if token == END_OF_TEXT:
        return -5.0
    if token[:1] in set("123456789") or "#" in token or is_non_latin(token):
        return 2.5 if "#" in token else 3.0
    if token.endswith("\n") or token.strip() in CLOSERS:
        return -1.0
    if token.startswith(" "):
        return -0.5 if word in STOP_WORDS else 0.2
    if word in CATALOG_NOUNS:
        return -2.5
    if word in PROGRAMMING_OR_IMPERATIVE:
        return 4.5
    if word in STOP_WORDS:
        return 0.5
    if token.isascii() and token.isalpha():
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first:
        return carry, (-1.5 if token == "··" else 0.0)
    return carry, start_value(token)

