"""A sparse, lexical approximation of a tabular-data/text contrast.

CSV, Excel, pandas, spreadsheet names, plotting axes and data-reporting
phrases get negative values. Statements and 'in terms' get positive values.
A few structured-text cues (table tags, MIME fields, reference attributes,
and export-interface declarations) have their own estimates. Magnitudes
are coarse estimates from training examples, not a complete semantic model.
Only the last 200 characters are retained, resetting between documents.
"""
import re

READS = ()


def predict(token, history):
    word = token.strip().lstrip('._($/<').lower()
    h = history.lower()
    joined = h + token.lower()
    if word == 'csv':
        if token.startswith('.'):
            return -2.8
        if token.startswith('_'):
            return -3.4
        if re.search(r'import\s*$', h):
            return -9.3
        return -5.8 if word == token.strip() else -4.0
    if word in {'xlsx', 'xls', 'lsx'} or re.search(r'x(?:lsx|ls)$', joined[-10:]):
        return -3.8
    if word == 'excel':
        if token.strip() == 'excel' and re.search(r'(to|they|we|not only)\s*$', h):
            return -0.6
