        return -6.0 if token == 'excel' and whole_identifier else (
            -4.8 if token.startswith(('.', '_')) else -3.5
        )
    if word in {'pandas', 'dataframe', 'dataframes', 'workbook', 'workbooks'}:
        if word == 'pandas' and re.search(r'import\s*$', h):
            return -5.5
        return -2.0 if token.startswith('.') else -3.2
    if joined.endswith('pandas') or (word in {'frame', 'frames'} and h.endswith('data')):
        return -2.5
    if word in {'pd', 'df'} and token.strip().lstrip('_(') in {'pd', 'df'} and (
        token.startswith('_') or re.search(r'(?:^|[^\w])(?:pd|df)$', joined)
    ):
        return -2.5 if word == 'pd' else -0.9
    if re.search(r'spread\s*sheets?$', joined):
        return -5.7
    if word in {'worksheet', 'worksheets'}:
        return -1.2
    if word in {'sheet', 'sheets', 'heet', 'heets'}:
        if re.search(r'(data|excel|google|balance)\s*$', h):
            return -3.0
        if token[:1].isupper() and not token.startswith(' '):
            return -2.4
        if re.search(r'excel|csv|workbook|worksheet|column|spreadsheet|dataframe|\bdf\b', h):
            return -1.9
        return -0.35
    if re.search(r'\btab(?:ular|ulated|ulation|ulate)$', joined[-24:]):
        return -3.8
    if word in {'table', 'tables'}:
        if not h:
            return -3.3
        if re.search(r'(?:data[ .]?|print|show|supplementary)\s*$', h):
            return -3.0
        return -0.5
    if word == 'pyplot':
        return -3.0
    if word in {'thead', 'tfoot'} or joined.endswith('tablefoot'):
        return -2.7
    if token.startswith('.') and word in {'iloc', 'writerow', 'columns'}:
        return -3.2 if word != 'columns' else -1.9
    if word in {'row', 'rows', 'column', 'columns', 'cell', 'cells'}:
        return -0.5 if token[:1] in '._(' or token[:1].isupper() else -0.15
    if word in {'header', 'headers'}:
        return -4.5 if re.search(r'column\s*$', h) else -0.5
    if word == '-axis':
        return -0.65
    if word in {'axis', 'axes'}:
        return -1.4 if re.search(r'(vertical|horizontal|[xy])\s*$', h) else -0.08
    if word in {'graph', 'graphs', 'chart', 'charts', 'scatter'}:
        if re.search(r'(bar|line|data)\s*$', h):
            return -4.2
        return -0.2
    if word in {'statement', 'statements'}:
        return 0.85 if token.startswith(' ') and token.strip().islower() else 0.3
    if word == 'terms':
        if re.search(r'in\s*$', h):
            return 2.1 if re.search(r'(answer|express).{0,90}in\s*$', h) else 0.85
        return -0.08
    if word == 'format':
        return 0.7 if re.search(r'(output|text|pdf)\s*$', h) else -0.03
    if word == 'as' and re.search(r'pandas\s*$', h):
        return 0.1
    if word in {'are', 'not', 'shown', 'processing', 'recording', 'analysis'}:
