            return -0.8 if word == 'are' else -1.3
    if word == 'in' and re.search(r'(summarized|listed|tabulated|presented)\s*$', h):
        return -0.9 if re.search(r'data|results|table|values|parameters', h) else -0.15
    if word == 'the' and re.search(
        r'(shows|show|displays|display|record|presents|report|gives)\s*$', h
    ):
        return -1.3 if re.search(r'table|figure|chart|graph|data', h[-100:]) else -0.2
    if word == 'as' and re.search(
        r'(expressed|presented|shown|provided|represented|plotted)\s*$', h
    ):
        return -2.8 if re.search(r'data|results|statistical|mean|values', h) else -0.6
    if word in {'expressed', 'presented', 'represented', 'shown'}:
        if re.search(r'data|results|statistical|mean', h):
            return -0.8
    if word == 'below':
        if re.search(r'(table|tables|graph|chart|figure)\s*$', h):
            return -1.8
        if re.search(r'answer\s*$', h):
