import re

READS = ()
PREPOSITIONS = {'of', 'in', 'at', 'by', 'to', 'for', 'with', 'from', 'on'}
REFERENCE = re.compile(r'(?<=[A-Za-z.)]), +[0-9]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
