            references = len(REFERENCE.findall(tail))
            code = any(c in tail[-250:] for c in '{}[]=;')
            value = 0.1 + min(references, 12) * (0.03 if code else 0.15)
        elif previous.endswith('.'):
            value = 0.06
    elif token in (':', ','):
        lower = tail.lower()
        if lower.endswith('instance of'):
            value = 1.5 if token == ':' else 1.9
        elif lower.endswith('educated at'):
            value = 1.0 if token == ':' else 1.3
        elif token == ',' and lower.endswith('border with'):
            value = 3.5
        elif token == ',' and word in PREPOSITIONS:
            if len(REFERENCE.findall(tail)) >= 3:
                value = 3.8
    elif token.strip().lower() == 'also' and word == 'see':
        heading = re.search(r'(?:^|\n)\s*See$', tail)
        value = 4.2 if heading else 1.9
    return (doc, token, (tail + token)[-600:]), value

"""Surface-spelling detector, dominated by institute and -stitut- words.

Institute/Institut/istituto spellings are strongly positive; institution,
substitute, statute, Stiftung and intuit- forms have smaller responses.
