        _, first, repeated, position, line_start, previous, before_previous = carry
        position += 1
        repeated = repeated and raw == first

    if repeated:
        value = opening(text)
    else:
        value = -0.004 if position < 32 else -0.00075
        if text == '\r':
            value = -0.045
        elif text == '\x00':
            value = 0.0385
        elif text in IMPORTS and line_start:
            value = -0.041
        elif text in ('<think>', '</think>', '<|im_start|>', '<|im_end|>'):
            value = -0.0275
        elif text == '.\n':
