import regex

READS = ()


def onset(token):
    word = token.strip()
    if token.startswith('<|'):
        return 1.93
    if token.isspace():
        if token == ' ':
            return 0.59
        return 0.6 if '\n' in token else 1.3
    if word.isdecimal():
        return 0.94
    if word.isascii() and word.isalpha():
        if token.startswith(' '):
            return 1.36 if word.istitle() else 1.57
        return 2.44 if word.istitle() else 2.03
    if regex.search(r'\p{Script=Han}', word):
        return 1.69
    if any(c.isalpha() for c in word):
        return 1.85
    return 0.88


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        age, first, repeating = 0, prefix.token_bytes[-1], True
    else:
        age, first = carry[1] + 1, carry[2]
        repeating = carry[3] and prefix.token_bytes[-1] == first
    state = (document, age, first, repeating)
    if repeating:
        value = onset(token)
    elif age == 1 and first == b'1' and token == '2':
        value = 2.05
    elif age == 1 and first == b'Title' and token == ':':
        value = 2.71
    else:
        value = 0.003 + 0.055 / (1 + age / 35)
    return state, value

