"""Component layers.1.mlp.down_proj:6049 — the letter "r", in any alphabet.

What it does: it reads the current token and writes a signal that is large when the
token is an "r" sound or letter. The activation is about:

- 1.0 for a short Latin token containing r ("r", " r", "ar", "or", "re", "ARS", "rr"),
  0.6 for a longer Latin word containing r ("great", "there", "result"), plus 0.3 for an
  all-caps token;
- about 1.0 for the r-like letters of other alphabets: Cyrillic р, Greek ρ, Czech ř,
  Thai ร, Arabic ر, Hebrew ר, Devanagari र, and the r-row kana (ら り る れ ろ, ラ リ ル レ ロ);
- about 1.0 for the digits 3, 4 and 9 (which carry the same signal, weaker);
- about 0.45 for a byte fragment that decodes to U+FFFD (part of a multi-byte character);
- about 0 for everything else (and about 0.1 for other non-Latin text).

It has no memory: each prediction depends only on the newest token's text.
"""

READS = ()

# Letters whose sound is "r": Cyrillic er, Greek rho, Czech r-caron, Thai ro,
# Arabic reh, Hebrew resh, Devanagari ra, and the ra-row of hiragana/katakana.
R_LETTERS = frozenset("РрΡρŘřรر" + "רर" + "らりるれろラリルレロ")

# Typical activation (in the component's units) for each kind of token.
SHORT_R = 0.95  # Latin token of up to 3 characters with an r: "r", "ar", "or", "re"
LONG_R = 0.6  # longer Latin token with an r: "great", "there", "Calculator"
UPPER_BONUS = 0.3  # added for all-caps Latin tokens with an r: "ARS", "RC"
OTHER_R = 1.0  # r-letters of other alphabets
DIGIT = 1.0  # the digits 3, 4 and 9
REPLACEMENT = 0.45  # a partial multi-byte character (decodes to U+FFFD)
NON_R_LATIN = 0.03  # ordinary Latin text without r
NON_R_OTHER = 0.1  # other non-Latin text


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    if "�" in token:
        value = REPLACEMENT
    elif text in ("3", "4", "9"):
        value = DIGIT
    elif text and all(c.isascii() for c in text):
        if "r" in text.lower():
            value = SHORT_R if len(text) <= 3 else LONG_R
            if text.isupper():
                value += UPPER_BONUS
        else:
            value = NON_R_LATIN
    elif any(c in R_LETTERS for c in text):
        value = OTHER_R
    else:
        value = NON_R_OTHER
    return carry, float(value)

