        elif fragment.lower().endswith('w') and s.startswith(('or', 'ör')):
            value = 7.0 if s == 'ört' or token.isupper() else 4.5

        if old.endswith(('or', 'ur')):
            value += 0.15
            if normal.startswith(('d', 't')):
                value += 1.2
        if old.endswith('r') and s in ('ds', 'dn'):
            value += 1.2
        if old[-1:] in ('a', 'e', 'i', 'o', 'u') and normal.startswith(('rd', 'rt')):
            value += 0.8
        if fragment.endswith('вор') and s.startswith('д'):
            value += 4.0

    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = ('', '', '')
        fragment = ''
    else:
        _, recent, fragment = carry
    token = prefix.token_strings[-1]
    s = token.strip().lower()
    p, q, r = recent  # previous token, two back, three back
    value = _list_response(token, recent)
    value = _spelling_response(token, recent, fragment, value)

    if token and token[0].isalpha():
        fragment = (fragment + token)[-24:]
    else:
        fragment = re.split(r'[^\w]+', token)[-1][-24:]
    return (doc, (s, p, q) if s else recent, fragment), value

programs.haiku:
"""layers.1.mlp.down_proj:6051, as a readable rule over the text so far.

What it does: this component is an "alternative word" detector with a sign.
  * Strongly negative on the word that closes an alternative in a list, the "other" in
    "X or other Y" (about -11 after "or", about -6 after "and"). The same holds for its
    kin after "or"/"and": another, otherwise, similar, whatever, something, any, anything,
    even, some, else. A determiner (a, an, any, some) may sit in between: "or a similar".
    "any other" and "some other" are moderately negative (about -2).
  * Negative on the "etc." list-ending words of other scripts: 等, など, 등, 或其他.
  * Positive on the spelling pieces of the word "word": "wor", "wör", "wort", "Wörter",
    "ворд", "вор" (as in кроссворд), about +1 to +7, and on "word"/"words", about +0.5.
  * Close to zero everywhere else, including ordinary "other" after "the", "with", "of".

Why: the component is largest on "or other", which is what its switch-off effect mostly
depends on. Predicting from the previous token and the current token captures about as
much variance as a bigram lookup table would.
"""

READS = ()

# Words that open an alternative after "or" and their typical activation there.
AFTER_OR = {
    "other": -10.7, "another": -6.0, "otherwise": -5.2, "similar": -5.1, "whatever": -5.0,
    "something": -3.6, "any": -3.3, "anything": -2.8, "even": -2.2, "others": -2.4,
    "some": -1.7, "else": -1.5,
}
# The same after "and", which is weaker.
AFTER_AND = {"other": -5.7, "similar": -1.8, "others": -1.2, "any": -0.7}
# Determiners that may sit between "or"/"and" and the alternative word.
DETERMINERS = {"a", "an", "any", "some"}
# List endings in other scripts: Chinese 等 and 或其他, Japanese など, Korean 등.
LIST_ENDINGS = {"等": -2.0, "など": -1.8, "등": -1.8, "或其他": -6.0, "或者其他": -8.5}
# Spelling pieces of "word" (wor, wör, wort, wörter, ворд, вор), by the last three tokens.
WORD_PIECES = {
    "wörter": 7.0, "wort": 3.2, "worte": 3.5, "wör": 4.6, "wor": 3.6,
    "ворд": 7.5, "вор": 1.3, "word": 0.5,
}
WORD_TOKENS = {"word": 0.6, "words": 0.9}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip().lower()
    prev = toks[-2].strip().lower() if len(prefix) > 1 else ""
    before = toks[-3].strip().lower() if len(prefix) > 2 else ""
    if cur in LIST_ENDINGS:
        return None, LIST_ENDINGS[cur]
    if prev in DETERMINERS and before == "or":
        prev = "or"
    if prev == "or" and cur in AFTER_OR:
        return None, AFTER_OR[cur]
    if prev == "and" and cur in AFTER_AND:
        return None, AFTER_AND[cur]
    if prev in ("any", "some") and cur == "other":
        return None, -2.0
    if cur in WORD_TOKENS:
        return None, WORD_TOKENS[cur]
    tail = "".join(toks[-3:]).lower()
    for piece, value in WORD_PIECES.items():
        if tail.endswith(piece):
            return None, value
    return None, 0.0

"""layers.1.mlp.down_proj:6052 -- the "decision / permission / request" complement feature.

What it does: it lights up on the word 'to' (and 'for') that introduces what someone
decides, agrees to, is allowed or asked to do, and weakly on the decision or request word
itself. Examples: "agreed [to]", "permission [to]", "the power [to]", "reminding them [to]",
"asked [for]", "a request [for]". Strongest after words of choosing, agreeing, refusing,
requesting, permitting and offering. Near zero on 'to' in fixed phrases ("due to",
"according to", "related to") and after "need", "have", "able", "used", "going".

Why: the component's output helps predict the complement that follows these words. It is
a small, word-driven feature: it reads only the previous word, so it is a lexicon, not a
model of meaning, and it misses context beyond one word.

The main function is `step`. Its values are fixed by hand, set from a least-squares fit
on 4,096 training rows.
"""

READS = ()

# Verbs and nouns of choosing, agreeing, requesting, permitting, offering, persuading.
CHOICE = {
    "agree", "agreed", "agreement", "decide", "decided", "decides", "decision", "choose", "chose",
    "chosen", "choice", "option", "refuse", "refused", "permission", "permit", "authority",
    "motion",
    "request", "requested", "asked", "ask", "asks", "asking", "offer", "offered", "promise",
    "promised", "plan", "plans", "planned", "committed", "commitment", "determined", "allowed",
    "allow", "invited", "encouraged", "told", "forced", "urged", "persuaded",
}
# Nouns, adjectives and words after which 'to' starts an infinitive of opportunity or purpose.
ABILITY = {
    "chance", "opportunity", "power", "right", "rights", "ability", "capacity", "willing",
    "desire", "attempt", "time", "ready", "like", "love", "tried", "trying", "try", "hope",
    "not", "is", "was", "as", "or", "and", "order", "way",
}
# Object pronouns and people nouns that are told or invited to do something: "reminded them to".
PEOPLE = {"me", "him", "her", "us", "them", "you", "everyone", "people", "students", "users"}
# 'to' in fixed phrases, or after need / have / able / going: no activation.
FLAT = {
    "due", "according", "related", "compared", "similar", "equal", "close", "respect", "prior",
    "relating", "connected", "attached", "corresponding", "referred", "adjacent", "belong",
    "belongs", "back", "return", "returned", "correspond", "leads", "lead", "leading", "led",
    "need", "needs", "have", "has", "used", "able", "going", "up", "continue", "continues",
    "seems", "seem", "relative", "refers", "refer",
}
# Verbs of asking or calling: 'for' after them is a request for something.
FOR_REQUEST = {
    "ask", "asked", "asking", "asks", "request", "requested", "called", "call", "calls", "apply",
    "applied", "applying", "vote", "voted", "motion", "push", "pushed", "demand", "demands",
    "argued",
}


def _word(prefix, i):
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    cur = _word(prefix, -1)
    prev = ""  # the previous word, if it is in the same document
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = _word(prefix, -2)
    if cur == "to":
        if prev in CHOICE:
            return None, 1.9
        if prev in PEOPLE:
            return None, 1.1
        if prev in ABILITY:
            return None, 0.8
        if prev in FLAT:
            return None, 0.0
        return None, 0.3
    if cur == "for":
        if prev in FOR_REQUEST:
            return None, 1.9
        return None, 0.15
    if cur in CHOICE:
        return None, 0.4
    return None, 0.0

programs.sol:
"""A sparse multilingual surface-form detector, not one unified semantic class.

Strong positives include manuscript, rice, pole, and rope/reeling characters;
weaker positives include text and program terms. A few manuscript/application
collocations change their strengths. UTF-8 fragments can fire even before a
character is complete, including specified Han and Hangul character families.
Other rules cover selected symbols and document openings. All other tokens
are zero except for a small frequency-based opening-token baseline. State
keeps only UTF-8 leftovers, the previous token, and document-opening status.
"""
import codecs
from wordfreq import zipf_frequency

READS = ()
DETERMINERS = {
    "the", "a", "an", "this", "that", "these", "those", "some", "any"
}

# Incomplete UTF-8 prefixes of these character/syllable families.
FRAGMENT_FAMILIES = tuple(
    (ch.encode("utf-8")[:2], strength)
    for ch, strength in (
        ("稲", 0.8),  # grain characters
        ("繰", 0.7),  # silk/thread characters
        ("簡", 2.5),  # bamboo characters
        ("翘", 2.4),  # wing characters
        ("権", 2.5),  # wood characters
        ("측", 2.0),
        ("브", 1.3),
        ("뿐", 1.2),
    )
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        n, previous, tail, first, leading = 0, '', b'', b, True
    else:
        _, n, previous, tail, first, leading = carry
        leading = leading and b == first
    # Decode just the new text, retaining an unfinished UTF-8 character.
    data = tail + b
    s, consumed = codecs.utf_8_decode(data, 'ignore', False)
    pending = data[consumed:]

    value = 0.0
    if n == 0:
        word = s.strip()
        value = -0.31
        if word.lower() in DETERMINERS:
            value += 0.29
        if word.startswith('<'):
            value += 0.43
        if word.isascii() and word.isalpha():
            if zipf_frequency(word, 'en') >= 5:
                value += 0.12
    if s == '稿':                       # draft/manuscript
        value = 4.5
        if previous.endswith('撰'):
            value = 7.8
        elif previous.endswith(('草', '赶')):
            value = 5.5
        elif previous.endswith(('样', '审')):
            value = 3.2
    elif s in {'稲', '稻', '水稻'}:      # rice
        value = 7.3 if s == '稲' else 3.5
    elif s in {'杆', '竿'}:              # rods/poles
        value = 2.8
    elif s in {'绳', '縄'}:              # rope
        value = 7.3 if s == '縄' else 4.5
    elif s == '繰':                     # reeling/winding; also repetition
        value = 6.0
    elif s.endswith('文字'):
        value = 1.5
    elif s == '程序':
        value = 0.5 if previous.endswith('应用') else 1.6
    elif s == '应用程序':
        value = 0.12 if previous.endswith(('主', '子')) else 0.8
    elif s == '代码':
        value = 0.4
    elif s == '졸':
        value = 2.6
    elif s == '몰':
        value = -4.7
    elif s == '権':
        value = -2.5
    elif s == '原始':
        value = 1.9
    elif s.strip() in {'rod', 'Rod', 'rods', 'Ro', 'ро'}:
        value = 0.8
    elif s in {'穗', '棉', '藤', '纲'}:  # grain ears, cotton, vine, rope
        value = 1.3
    elif s in {'紹', '絵'}:           # introduce; picture
        value = 0.9
    elif s == '👨':
        value = 2.4
    elif s == '\u2028':             # Unicode line separator
        value = -3.4
    elif s == '\u202f':             # narrow no-break space
        value = -1.4
    elif s == '⨯':                    # vector/cross product sign
        value = -3.1
    elif s == '··':
        value = -3.04

    if pending and (len(b) == 1 or b == pending):
        for beginning, strength in FRAGMENT_FAMILIES:
            if pending == beginning:
                value = strength
                break

    if s == 'り' and previous == '繰':
        value = 1.8

    if n == 1 and previous == '1' and s == '2':
        value = -3.83
    elif n == 1 and previous == 'Hy' and s == 'dro':
        value = -7.27
    elif leading and s == '\r':
        value = -4.06
    elif leading and s == '^^^^':
        value = -3.99
    elif n == 0 and s == '//\n':
        value = -5.82
    elif n == 0 and s == '<|endoftext|>':
        value = -3.49

    return (doc, n + 1, s, pending, first, leading), value

"""Approximate formatting-boundary detector, not a general word predictor.

It excites on indentation after numbered code gutters, diff signs, and
written-out newlines; real line endings usually suppress it. Whitespace
widths are measured within the current token, with extra sensitivity to
four-column spacing patterns. Nonbreaking spaces, a few indented code
keywords, secure URL separators and Markdown links have their own cues.
The state resets between documents; most other tokens are predicted zero.
"""
import math

READS = ()
HORIZONTAL = ' \t\xa0'
# Words that commonly begin an indented statement or declaration.
LINE_STARTERS = {
    'for': 1.0, 'foreach': 0.65, 'while': 0.65, 'do': 0.65,
    'const': 1.02, 'var': 1.02, 'let': 0.78, 'final': 0.5,
    'try': 0.73, '$': 0.85,
}
TAB_STARTERS = {'import', 'from', 'export', 'use', 'type', 'func', 'function'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before, seen_content, line = '', '', False, ''
    else:
        _, prev, before, seen_content, line = carry
    gutter = line.strip().rstrip(':')
    numbered = len(gutter) >= 2 and gutter.isdigit()
    next_line = (line + s).rsplit('\n', 1)[-1]
    if len(next_line) > 40 or next_line.strip(' \t0123456789:'):
        next_line = '?'
    state = (doc, s, prev, seen_content or bool(s.strip()), next_line)
    newline = prev.endswith('\n')
    horizontal = bool(prev) and not prev.strip(HORIZONTAL)
    escaped_tab = prev == '\\t' or (prev == 't' and '\\' in before)
    escaped = prev in ('n', '\\n') and (prev == '\\n' or '\\' in before)
    diff_sign = prev in ('+', '-')

    if s and not s.strip(HORIZONTAL):
        spaces, tabs = s.count(' '), s.count('\t')
        if tabs:
            if not seen_content and s == '\t':
                value = -1.08
            elif newline:
                if spaces and s.endswith('\t'):
                    value = 0.5 + 0.15 * spaces
                else:
                    value = 0.03 * spaces
            elif horizontal and '\t' in prev and not spaces:
                value = 0.52 if tabs == 1 and ' ' not in prev else 2.15
            elif prev.isdigit() or diff_sign or horizontal:
                if spaces:
                    value = 1.3 + 0.38 * math.log1p(spaces)
                    if spaces % 4 == 3:
                        value -= 0.12
                else:
                    value = 1.3 if tabs == 1 else 2.1
            else:
                value = 0.45
        elif '\xa0' in s:
            n = s.count('\xa0')
            if newline:
                value = -0.12
            elif numbered and n == 1:
                value = 1.6
            elif n > 1 and ('`' in prev or (prev and not prev.strip(' '))):
                value = 1.4
            elif n % 4 == 3:
                value = 1.15 + (0.55 if horizontal else 0.0)
            elif n == 1:
                if prev and not prev.strip('\xa0'):
                    value = 0.6 + (1.2 if len(prev) % 4 == 3 else 0.0)
                else:
                    value = 0.25 if horizontal or prev.isdigit() else 0.05
            elif n == 8:
                value = 0.5
            else:
                value = 0.1
        elif numbered and spaces >= 4 and (
            prev.isdigit() or prev.endswith(':')
        ):
            value = 1.25 + 0.45 * math.log1p(spaces)
        elif escaped:
            value = 0.6 + 0.4 * (spaces % 4 == 1)
            value += 0.35 * (prev == 'n')
        elif newline:
            if spaces % 4 == 1:
                value = 0.43 if spaces == 1 else 0.26
            else:
                value = -0.05
        elif horizontal and '\t' in prev:
            value = 0.65 if spaces == 1 else 1.9
        elif diff_sign or prev.strip() == '|':
            value = 0.4 + 0.2 * math.log1p(spaces)
        elif prev.endswith(('"', "'")):
            value = 0.5 + 0.15 * math.log(spaces)
        elif spaces > 1 and not horizontal and not prev.isdigit():
            value = 0.25 if spaces % 4 == 3 else 0.05
        else:
            value = 0.0
        return state, min(2.7, value)

    word = s.strip(HORIZONTAL)
    if '\n' not in s and (horizontal or newline or escaped or escaped_tab
                           or (s.startswith('\t') and prev.isdigit())):
        value = LINE_STARTERS.get(word, 0.0)
        if s.startswith('\t') and word in TAB_STARTERS:
            value = 0.95
        if value:
            value += 0.25 * s.startswith('\t')
            if newline and not s.startswith((' ', '\t')):
                value *= 0.6
            return state, value
    if (s.startswith('\t') and s[1:].isalpha()
            and prev and not prev.strip(' ')):
        return state, 1.1
    if s == '\\t':
        return state, 0.97
    if s == '://' and prev.strip() == 'https':
        return state, 1.08
    if s == '](':
        return state, 0.7
    if s == '``' and '\xa0' in prev:
        return state, 1.8
    if s == '\":':
        return state, 0.15
    if len(s) > 1 and not s.strip('·'):
        return state, 1.0
    return state, 0.0

"""Recognize short parenthetical abbreviations and their letter fragments.

Capital-heavy abbreviations respond negatively, most strongly on a plain ')'.
Matching their capitals to preceding word initials strengthens the response;
length, digits, separators and fused punctuation weaken it. There are small
responses to capital fragments inside parentheses and to ', such'. A separate
branch recognizes a document-initial 'Title:' field. Everything else is zero.
"""
import re

READS = ()
QUOTES = '\"\'“”‘’'


def initials_match(abbreviation, left):
    capitals = ''.join(c.lower() for c in abbreviation if c.isupper())
    words = re.findall('[A-Za-z]+', left)[-10:]
    initials = iter(word[0].lower() for word in words)
    return bool(capitals) and all(c in initials for c in capitals)


def abbreviation_value(inside, left):
    if not re.fullmatch('[A-Za-z][A-Za-z0-9&/-]{1,13}', inside):
        return 0.0
    caps = sum(c.isupper() for c in inside)
    if caps >= 2 and caps >= sum(c.isalpha() for c in inside) / 2:
        matched = initials_match(inside, left)
        value = -8.8 if matched else -7.0
        if any(c.isdigit() for c in inside):
            value = -4.0
        if len(inside) >= 6 and not matched:
            value *= 0.4
        if len(inside) == 2 and not matched:
            value *= 0.8
        if '-' in inside or '/' in inside:
            value *= 0.6
        return value
    if caps == 1:
        if len(inside) == 2:
            return -2.8
        return -1.0 if len(inside) <= 4 else -0.3
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    text, pos = ('', 0) if fresh else (carry[1], carry[2] + 1)
    value = 0.0
    opening = max(text.rfind('('), text.rfind('（'))
    if opening >= 0:
        inside, left = text[opening + 1:].strip(QUOTES), text[:opening]
        prose = not left or left[-1].isspace() or text[opening] == '（'
        if prose and not inside:
            if re.fullmatch('[A-Z]{1,4}', token):
                matched = initials_match(token, left)
                if len(token) == 1:
                    value = -1.8 if matched else -0.95
                else:
                    value = -2.4 if matched else -1.4
                if not re.search(r'[A-Za-z]{3,}\s*$', left):
                    value *= 0.25
            elif token == 'e':
                value = -0.7
        elif (prose and token.isalpha()
              and re.fullmatch('[A-Z][A-Za-z]{0,13}', inside)):
            value = -1.0
        closing = token.lstrip(QUOTES)
        if closing.startswith((')', '）')):
            value = abbreviation_value(inside, left) * (1 if prose else 0.18)
            if closing != ')':
                if closing == '）':
                    value *= 0.7
                elif '\n' in token:
                    value *= 0.15
                elif ',' in token or '、' in token:
                    value *= 0.55
                else:
                    value *= 0.8 if '-' in token else 0.3
    if pos == 0 and token == 'Title':
        value = 1.17
    if pos == 1 and text == 'Title' and token == ':':
        value = -11.0
    if token == ' such' and text.rstrip().endswith(','):
        value = -0.8
    text = (text + token)[-250:]
    if ')' in token or '）' in token:
        text = text[max(text.rfind(')'), text.rfind('）')) + 1:]
    return (doc, text, pos), value

programs.haiku:
"""Closing parenthesis of an acronym, e.g. "intensive care unit (ICU)".

The component goes strongly negative on the ")" that closes a short all-capitals
abbreviation placed in parentheses right after the phrase it abbreviates. It is
strongest when the abbreviation's letters are the initials of that phrase's words
("computer assisted design (CAD)"), weaker when they are not ("data acquisition
system (DAQ)"). It is mildly negative on the first capital letters of such an
abbreviation, just after the "(". Everything else is about zero.
"""
import re

READS = ()

SKIP = {"of", "and", "for", "the", "in", "on", "a", "an", "de", "la", "to", "with", "by"}
OPEN, CLOSE = "([（", ")]）"


def _inner_and_before(strings):
    """Text between the nearest open parenthesis (within 8 tokens) and the current token,
    and the text before that parenthesis. None unless the parenthesis follows a space."""
    n = len(strings)
    for k in range(n - 2, max(-1, n - 10), -1):
        if any(c in strings[k] for c in OPEN):
            if not strings[k].startswith(" "):
                return None, None
            return "".join(strings[k:-1]), "".join(strings[max(0, k - 12):k])
        if any(c in strings[k] for c in CLOSE):
            break
    return None, None


def _is_acronym(text):
    text = text.strip()
    for c in OPEN:
        text = text.replace(c, "")
    letters = [c for c in text if c.isalpha()]
    if not (2 <= len(letters) <= 8) or not re.fullmatch(r"[A-Za-z0-9&\-]+", text):
        return False
    return sum(c.isupper() for c in letters) >= max(2, 0.6 * len(letters))


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    cur = strings[-1]
    if any(c in cur for c in CLOSE):
        inner, before = _inner_and_before(strings)
        if inner is None or not _is_acronym(inner):
            return carry, 0.0
        letters = "".join(c for c in inner if c.isalpha())
        words = [w for w in re.findall(r"[A-Za-z]+", before) if w.lower() not in SKIP]
        initials = "".join(w[0] for w in words[-len(letters):]).upper()
        return carry, -7.0 if initials == letters.upper() else -5.0
    if len(strings) >= 2 and any(c in strings[-2] for c in OPEN):
        if cur.strip().isupper() and len(cur.strip()) <= 3 and cur.strip().isalpha():
            return carry, -1.0
    return carry, 0.0

programs.sol:
"""Approximate the opening-token pulse, including uniform opening repetitions.

Most of the component is a negative response before a document has acquired
varied context. Its size depends on readable token classes: grammatical
English words are stronger than digits, whitespace or punctuation. Once a
different token arrives, only a small Unix-directory-name response remains.
These are class averages, not a table of token-specific amplitudes.
"""
import regex

READS = ()
PREPOSITIONS = set('of in for from with by at on into onto upon under over '
                   'between through about'.split())
