    value -= 0.09 * recent
    if ordinary_word(word):
        value += 0.31 - 0.46 * recent
    if text.endswith((':', '#')):
        value += 0.80
        if before.isspace():
            value += 0.30
    if text.endswith(('"', "'", '(', '[', '{')):
        value += 0.50
    if text.endswith((')', ']', '}')):
        value -= 0.28
    if (word in UNITS or len(word) == 1 or text.endswith('  ')
            or any(c.isdigit() for c in word)):
        value -= 0.10
    if word in COMMANDS:
        value += 0.51
    if before.isspace() and word in SHORT_PREPOSITIONS:
        value += 0.40
    if before.isspace() and text.endswith(('=', '>', '<')):
        value += 0.65
    if re.search(r'\s-[a-zA-Z]+$', text) and before.isspace():
        value += 0.45
    if re.search(r'\bFile$', text):
        value += 0.60
    if after[:1].islower():
        value -= 0.08
    if after.startswith('_'):
        value -= 0.14
    if after and not after[0].isalnum() and after[0] != '_':
        value -= 0.14
    if after[-1:].isspace():
        value -= 0.08
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = -0.002
    if token == '/usr':
        value = 1.4
    elif '/' in token:
        value = slash_value(token, text)
    elif token == '\n' and text.endswith('<|im_start|>user'):
        value = -0.18
    elif token.rstrip('\r\n') == ':' and re.search(r'\.[a-zA-Z]{1,5}$', text):
        value = -0.52 if token == ':' else -0.16
    elif token == ' line' and re.search(r'File "[^"\n]+",$', text):
        value = -0.35 if text.endswith('>",') else -0.80
    elif token == 'usr' and text.endswith('/'):
        value = 1.2
    elif token.strip() == '州':
        value = 1.8
    elif '州' in token:
        value = 0.65
    elif token.strip() == '洲':
        value = 1.05
    elif token.strip() == '주':
        value = 0.55
    elif token.strip().lower() == 'zhou':
        value = 1.2
    elif token == '_modules' and text.endswith('node'):
        value = 0.28
    elif token == '\r' and not text.strip('\r'):
        value = 6.39
    return (doc, (text + token)[-100:]), float(value)

"""A lexical detector, chiefly for time/date APIs and module loading.

Time words in prose are weak; imports, constructors and clock calls are
strong.  Message/error fields and JSON parsing have the opposite sign.
Han cotton/fineness words have a separate negative response, including
characters completed by a UTF-8 continuation token. Unrecognized tokens
return zero. A short text/byte tail is retained and resets at document boundaries.
"""
import re

READS = ()
FINE_FIBER_HAN = frozenset("细細纤纖")  # fine, thin, slender
COTTON_HAN = frozenset("棉绵綿")


def response(token, previous, tail):
    s = token.strip()
    p = previous.strip()
    if s in FINE_FIBER_HAN:
        return -3.8
    if s in COTTON_HAN:
        return -6.2
    if s == '絮':  # floss, catkins
        return -2.8
    if s == '棉花':
        return -2.4
    if s in {'细细', '细腻', '细微', '细致'}:  # fineness/delicacy
        return -1.9

    if s == 'require':
        if p == '=':
            return 4.9
        return -0.08 if token.startswith(' ') else 0.2
    if s == '.com' and re.search(r'(?<![\w.])github$', tail):
        return 2.2 if previous.startswith('"') else 1.55
    if s == '/repos' and tail.endswith('api.github.com'):
        return 0.8
    if s == '.raw' and p == 'String':
        return -3.7
    if s == '.parse':
        return -1.2 if tail.endswith('JSON') else 0.15
    if s == '.stringify' and tail.endswith('JSON'):
        return -0.45
    if s == '.Status' and tail.endswith('http'):
        return -0.75

    if s.lower().lstrip('._') in {'message', 'messages'}:
        if s.startswith('.'):
            if p.lower() in {'e', 'err', 'error', 'exception', 'ex'}:
                return -2.45
            return -1.0
        if s.startswith('_'):
            return 0.95 if tail.endswith('send') else -0.35
        if token.startswith(' '):
            return -0.08
        return -0.8 if s.islower() else -0.35
    if s == 'document' and p == '=':
        return 0.7
    if s == 'Immediate' and tail.endswith('set'):
        return 4.5
    if s == 'getTime':
        return 1.2
    if s == '.now':
        return 2.9 if tail.endswith('datetime') else 0.1
    if s == '.datetime':
        return -0.2 if tail.endswith('datetime') else 0.15

    # Separators distinguish bare identifiers from ordinary spaced words.
    name = s.lstrip('._(/="')
    if name not in {'time', 'date', 'Time', 'Date', 'TIME', 'DATE', 'datetime'}:
        return 0.0
    lower = name.lower()
    if p == 'import' or (p == 'from' and not previous.startswith(' ')):
        return 6.4 if lower in {'time', 'date'} else 2.7
    if name == 'Date' and re.search(r'\bnew$', tail):
        return 5.7
    if name == 'Date' and p == 'instanceof':
        return 3.3
    if s == '.Date':
        if p in {'.util', '.sql'}:
            return 5.5
        return 3.2 if p == 'time' else 1.2
    if s == '.time':
        if re.search(r'\b(time|datetime|pygame|java)$', tail):
            return 6.0
        return 1.0
    if s == '.Time':
        return 1.5
    if token == 'time' and re.search(r'#\s*include\s*<$', tail):
        return 6.3
    if token == 'date' and tail.endswith('$('):
        return 5.6  # shell command substitution
    if token == 'date' and p == '`':
        return 3.2
    quoted = s.startswith('"') or tail.endswith('"')
    if name == 'time' and not token[:1].isspace() and quoted:
        return 2.4
    if token == 'date' and tail.endswith(("'", '"')):
        return 1.7
    if token == 'time' and p in {'a', 'm', 'c', '.m', '(m'}:
        return 4.3  # POSIX access/modification/change timestamps
    if name == 'time' and p in {'Long', '.DateTime', 'DateTime', '()'}:
        return 1.8
    if name == 'date' and p == 'type':
        return 1.0
    if name == 'time' and re.search(r'\t(User|System)$', tail):
        return 1.7 if p == 'System' else 0.8
    if name == 'time' and tail.endswith('(wall clock)'):
        return 0.55
    if name == 'Date' and p in {'public', 'private', 'protected', 'static', '+'}:
        return 3.4
    if p in {'=', ':=', 'return'} or previous == ' .':
        return 3.2 if lower != 'datetime' else 1.1
    indented = previous.isspace() and '\n' not in previous
    if p in {':', ',', '+', '*', '->'} or indented:
        return 1.2 if lower != 'datetime' else 0.5
    if not token[:1].isspace():
        if s.startswith('_'):
            return 0.6
        if name == 'Time':
            return 0.6
        return 1.15 if lower != 'datetime' else 0.5
    return 0.0


def complete_token(raw, recent):
    text = raw.decode('utf-8', errors='replace')
    if text == '\ufffd' and raw and 0x80 <= raw[0] < 0xC0:
        joined = (recent + raw).decode('utf-8', errors='replace')
        if not joined.endswith('\ufffd'):
            text = joined[-1:]
    return text


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, recent = '', '', b''
    else:
        _, previous, tail, recent = carry
    raw = prefix.token_bytes[-1]
    token = complete_token(raw, recent)
    value = response(token, previous, tail)
    return (doc, token, (tail + token)[-100:], (recent + raw)[-3:]), value

programs.haiku:
"""Date and time words used as code, plus JS `require`, `github.com`, and a few negatives.

What it does, in plain terms. The component reads the current token and the token before it.
It adds a positive amount when the current token is a date or time word used as code rather
than as English: `new Date(` (strongest), `x = time`, `import time`, `.time()`, `/date`,
`#include <time.h>`, `Date` as a type. The same words after an English word ("some time",
"the date", "Due date") give 0, and camel-case names like `.DateTime` give 0.
It also fires on `require` in `const fs = require(` and on `com` in `github.com`. It goes
negative on `.message` and on the Chinese character 细/細 ("fine, slender").
Everything else predicts 0. The sizes are rough means read off a sample of training text.
"""

READS = ()

DATE_TIME = {"date", "Date", "DATE", "time", "Time", "TIME", "datetime"}
CODE_BEFORE_WORD = {"import", "instanceof", "return", "typeof"}
NEGATIVE = {"细": -3.5, "細": -3.5}


def is_english_word(token):
    # an English word, with or without a leading space: " the", "Due", "rome"
    word = token[1:] if token.startswith(" ") else token
    return word.isalpha() and word.isascii()


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return None, 0.0
    token = prefix.token_strings[t]
    prev_token = prefix.token_strings[t - 1]
    prev = prev_token.strip(" ")
    word = token.strip(" ._/*(\t\n\"'")
    value = 0.0
    if word in DATE_TIME:
        if prev == "new":
            value = 4.7  # new Date(
        elif prev == "=":
            value = 2.3  # x = time
        elif token[:1] in "./":
            value = 2.5  # .time(), /date
        elif is_english_word(prev_token) and prev not in CODE_BEFORE_WORD:
            value = 0.0  # "some time", "the date", "Due date": English
        elif word[:1].isupper():
            value = 0.6  # Date, Time
        else:
            value = 1.2  # time, date
    elif word == "require" and prev == "=":
        value = 5.0  # const fs = require(
    elif word == "com" and prev == "github":
        value = 1.7  # github.com/...
    elif word == "message":
        value = -2.0 if token[:1] == "." else -0.5
    elif token.strip(" ") in NEGATIVE:
        value = NEGATIVE[token.strip(" ")]
    return None, float(value)

programs.sol:
"""Document-onset signal, with a polarity and size set by the opening token.

Chat and code openings, headings and English question words give large positive
values. Numbers and short lowercase fragments often give negative values.
The pulse continues through exact repeats of that token, then goes silent.
The small context-dependent remainder is not modeled.
"""
import regex

READS = ()

PREPOSITIONS = set(('of to in for on at by with from into over under about '
                     'between through after before as').split())
PRONOUNS = set(('you he she it we they me him her us them '
                 'my your his our their').split())
DEICTICS = set('this that these those there'.split())
CONJUNCTIONS = set(('and or but if so while because although '
                     'unless than then').split())
AUXILIARIES = set(('is are was were be been being am have has had do does did '
                    'can could will would shall should may might must').split())
QUESTIONS = set('what when where why how which who whom whose'.split())
DECLARATIONS = set('package import from using namespace const def void use'.split())


def onset(s):
    if s == '<|im_start|>':
        return 8.8
    if s == '<|endoftext|>':
        return 0.2
    if s.startswith('<|') or s.startswith('<tool') or s.startswith('</tool'):
        return 7.0
    if s.isspace():
        if '\n' in s or '\r' in s:
            return 1.1 if s.count('\n') == 1 else 1.7
        if '\t' in s:
            return 1.4
        return {1: -0.7, 2: 1.8, 3: 5.3}.get(len(s), 3.7)
    w = s.strip()
    spaced = s.startswith(' ')
    if w.isascii() and w.isdigit():
        if w in {'0', '9'}:
            return 0.1
        if w == '2':
            return -2.4
        return -7.0 if w == '7' else -5.0
    if any(c.isnumeric() for c in w) and not any(c.isalpha() for c in w):
        return -5.0
    if not any(c.isalnum() for c in w):
        if w == '#':
            return 5.1
        if w.startswith('##'):
            return 3.7
        if w == ',':
            return 2.6
        if '^' in w:
            return -3.8
        if w == '/':
            return -4.0
        if w == '.':
            return 0.1
        if w == '(':
            return 1.4 if spaced else -1.5
        return 0.6
    if w.isascii() and w.isalpha():
        low = w.lower()
        capital = w[0].isupper() and not spaced
        if w.isupper() and len(w) > 1:
            return 1.1 if len(w) <= 3 else 2.8
        if not spaced and w.islower() and low in DECLARATIONS:
            return 7.7
        if capital and low in QUESTIONS:
            return 7.8
        if low == 'the':
            return 6.3 if capital else 5.1
        if low in {'a', 'an'}:
            return 4.2 if capital else (2.5 if spaced else 0.4)
        if low == 'i':
            return 2.1 if capital else (1.4 if spaced else -1.0)
        if low in DEICTICS:
            return 5.3 if capital else 2.4
        if low in PREPOSITIONS:
            if capital:
                return 4.5
            if low == 'to':
                return 4.1 if spaced else 0.0
            if low in {'in', 'on', 'at', 'from'}:
                return 1.0 if spaced else -0.5
            return 2.8 if spaced else 0.0
        if low in AUXILIARIES:
            return 5.7 if capital else (4.9 if low == 'be' else 2.8)
        if low in CONJUNCTIONS:
            return 2.4 if capital else 2.8
        if low in PRONOUNS:
            return 3.8 if capital else 2.0
        if len(w) == 1:
            return (1.0 if capital else -2.4) if not spaced else -1.3
        if spaced:
            return 2.3
        if w[0].isupper():
            return 3.6
        return -0.5 if len(w) <= 2 else 1.8
    if regex.search(r'\p{Script=Han}', w):
        return 1.6
    if regex.fullmatch(r'\p{Script=Cyrillic}+', w):
        return -2.5 if len(w) == 1 and w.islower() and not spaced else 0.8
    return 1.0


def step(carry, prefix, upstream):
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    token = prefix.token_ids[-1]
    if start:
        value = onset(prefix.token_strings[-1])
        return (token, value), value
    if carry is not None and carry[0] == token:
        return carry, carry[1]
    return None, 0.0

programs.haiku:
"""Document-start detector for layers.1.mlp.down_proj:6066 (layer 1, MLP down-projection).

What it does: this component is silent (about 0) at almost every token. It fires only on
the first token of a document: the token right after <|endoftext|> (in a packed row, where
the document id changes), or the first token of a row. There the model has no earlier
context to attend to, so the response is set by the token's identity and kind:
- chat-template tokens such as <|im_start|> fire strongly (+8.8);
- capitalised English words ("What", "The", "This") and common function words
  (" the", " of", " is") fire positively;
- digits fire negatively, single lowercase letters and gibberish fragments a little
  negatively; CJK characters are mildly positive;
- the repeated middle-dot token "··" gives a large constant -8.3 wherever it occurs.
Everything else at a non-initial position is 0.
"""
import re

READS = ()

SPECIAL = re.compile(r"<\|[^|]*\|>")
DIGIT = re.compile(r" ?\d")
CAP_WORD = re.compile(r"[A-Z][a-z]+")
SPACE_WORD = re.compile(r" [a-z]+")
LOWER_WORD = re.compile(r"[a-z]+")
FUNCTION_WORDS = {" the", " of", " and", " to", " a", " is", " in", " it", " that",
                  " for", " on", " with", " as", " was", " be", " this", " what", " are"}


def first_token_value(s):
    """The component's activation at a document's first token, by what the token is."""
    if SPECIAL.fullmatch(s):
        return 8.8 if s == "<|im_start|>" else 6.8
    if DIGIT.fullmatch(s):
        return -3.5
    if CAP_WORD.fullmatch(s):
        return 4.5
    if s in FUNCTION_WORDS:
        return 3.2
    if SPACE_WORD.fullmatch(s):
        return 2.3
    if LOWER_WORD.fullmatch(s):
        return -1.0 if len(s) <= 2 else 0.4
    if s.strip() == "":
        return 0.6
    if any("一" <= c <= "鿿" for c in s):
        return 1.8
    return 1.0


def step(carry, prefix, upstream):
    t = prefix.position
    s = prefix.token_strings[t]
    if s == "··":
        return carry, -8.3
    starts = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts:
        return carry, 0.0
    return carry, float(first_token_value(s))

programs.sol:
"""Preverbal scope and aspect markers, approximated with grammatical rules.

The strongest negative responses are restrictive adverbs ("just", "only"),
negation, and particles meaning again, together, still or always. English
infinitive/gerund contexts and "let me / let's" strengthen the response;
determiners weaken it. French object clitics behave similarly. This is a
small lexical grammar, not a parser; unrecognized tokens predict zero.
Only the last two tokens are retained, resetting at document boundaries.
"""
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=8192)
def simplified(text):
    return _SIMPLIFY.convert(text)


DETERMINERS = set(
    'the a an this that these those my your his her its our their'.split()
)
MODALS = set('can could may might will would shall should must'.split())
PRONOUNS = set('i you he she we they it'.split())
BE = {'is', 'are', 'was', 'were', 'am', 'be', 'been', "'s", "'m", "'re"}
HAVE = {'has', 'have', 'had', "'ve"}

# Strengths for English scope, aspect and frequency modifiers.
ADVERBS = {
    'just': -0.74, 'merely': -0.66, 'simply': -0.41,
    'only': -0.27, 'not': -0.29, 'also': -0.14,
    'even': -0.12, 'actually': -0.26, 'first': -0.19,
    'always': -0.32, 'never': -0.23, 'ever': -0.11,
    'already': -0.14, 'still': -0.01,
}


def english(w, p, q, capitalized):
    if w not in ADVERBS:
        return None
    v = ADVERBS[w]
    if capitalized and w == 'first':
        return 0.0
    exhortation = p in {"let's", 'lets'} or (
        p in {'me', 'us', "'s"} and q == 'let'
    )
    if w == 'not' and not exhortation:
        if p in MODALS or p in {'do', 'does', 'did', 'need'}:
            return 0.03
        if p in BE or p in HAVE:
            return -0.04 if p not in {'are', 'were', "'re"} else -0.26
    if w == 'only':
        if p in DETERMINERS:
            return 0.13
        if p == 'not':
            return -0.05
    nominal_first = p in DETERMINERS or p == 'at' or p.endswith("'s")
    if w == 'first' and not exhortation and nominal_first:
        return -0.04
    if w in {'first', 'even'} and p in {'of', 'for', 'in', 'on', 'from'}:
        return -0.39 if w == 'first' else -0.08
    gain = 0.3 if w in {'ever', 'already', 'never'} else 1.0
    if exhortation:
        v -= 1.82 * gain
    elif p == 'to':
        v -= 1.51 * gain
    elif p in {'of', 'by', 'without', 'about'}:
        v -= 1.72 * gain
    elif p in {'for', 'from', 'in', 'on', 'than'}:
        v -= 1.07 * gain
    elif p in {'not', "'t", 'cannot', 'never'}:
        v -= 1.04 * gain
    elif p in {'while', 'when', 'maybe', 'perhaps'}:
        v -= 0.90 * gain
    elif p in {'and', 'or', 'but'}:
        v -= 0.22 * gain
    elif p in MODALS:
        v -= 0.24 * gain
    elif p in PRONOUNS:
        v -= 0.12 * gain
    elif p in {'are', 'were', 'am', "'m", "'re"}:
        v -= 0.25 * gain
    elif p in HAVE or p in DETERMINERS:
        v += 0.05
    return v * 0.65 if capitalized else v


# Mandarin adverbial particles and common preverbal modifiers.
# OpenCC lets the same rules handle traditional and simplified spelling.
# Together, continuously, always, forever, with effort, beforehand.
PERSISTENT_OR_EMPHATIC = set('一起 一同 一直 总是 永远 拼命 事先'.split())
# Repetition, first/only, manner and immediacy.
SCOPE_MANNER_IMMEDIACY = set(
    '再 先 只 仅 好好 真的 马上 立即 立刻 多多 一边 到处'.split()
)
# Additive/degree particles, continuation, and go/give before an action.
PREVERBAL = set('也 都 就 太 挺 去 给 给我 给你 继续 老 以后 则'.split())
# Light negation, focus, degree and recency modifiers.
LIGHT_MODIFIERS = set('不 也不 就不 都不 只是 仍然 还是 直接 才 多 少 真 新'.split())
MODAL_ENDINGS = set('要能该须需会请让不别可想愿敢得')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev = before = ''
    else:
        _, prev, before = carry
    s = prefix.token_strings[-1]
    w = s.strip().replace('’', "'")
    p = prev.strip().lower().replace('’', "'")
    q = before.strip().lower()
    state = (doc, s, prev)
    # Do not mistake a suffix inside another word for a function word.
    boundary = not prev or s[:1].isspace() or not prev[-1:].isalnum()
    if boundary:
        v = english(w.lower(), p, q, w[:1].isupper())
        if v is not None:
            return state, v
    c = simplified(w.lstrip('，。；：、'))
    # A preceding modal or prohibition makes a following modifier stronger.
    boost = float(simplified(prev[-1:]) in MODAL_ENDINGS)
    if c in PERSISTENT_OR_EMPHATIC:
        return state, -1.95 - boost
    if c in SCOPE_MANNER_IMMEDIACY:
        return state, -0.93 - boost
    if c in PREVERBAL:
        return state, -0.63 - 0.7 * boost
    if c in LIGHT_MODIFIERS:
        return state, -0.33 - 0.7 * boost
    # Japanese/Korean focus: only, just, up to, even.
    if w in {'だけ', 'ただ', 'ばかり', 'まで', 'でも', '만'}:
        return state, -1.9 if w == 'ばかり' else -0.65
    # Slavic and Portuguese negators.
    if boundary and w.lower() in {'не', 'nie', 'não'}:
        return state, -0.67 if w.islower() else -0.96
    # Russian just/immediately; Korean all/together/too.
    if boundary and w in {'просто', 'сразу', '다', '함께', '모두', '너무'}:
        return state, -1.25
    # French articles/object clitics, strengthened in verb-introducing contexts.
    if boundary and w in {'le', 'les', 'se', 'ne'}:
        v = -0.50 if w.lower() == 'les' else -0.17
        if p == 'de':
            v = -3.6
        elif p == 'ne':
            v = -0.9 if w in {'ne', 'se'} else -3.3
        elif p in {'à', 'en', 'sans'}:
            v -= 1.6
        elif p in {'pour', 'pas', 'je', 'tu', 'on'}:
            v -= 1.0
        elif p in {'et', 'ou', 'nous', 'vous'}:
            v -= 0.55
        return state, v
    if (boundary and w in {'me', 'te', 'nous', 'vous', 'lui'}
            and p in {'de', 'à', 'pour', 'ne'}):
        return state, -1.2
    if w == "'en":
        return state, -1.3
    if w == "'y":
        return state, -0.75
    return state, 0.0

"""Score standalone spaces using their left context: indentation and date commas
raise the score; letters, digits and line breaks usually lower it. A running
count recognizes prose that double-spaces after words and lowers its score.
Tabs and nonbreaking spaces respond mainly to repetition; backticks give a
smaller response. All other tokens receive zero. No future tokens are used.
"""
import calendar
import re

READS = ()
MONTH_NAMES = set(calendar.month_name[1:]) | set(calendar.month_abbr[1:])
MONTHS = '|'.join(MONTH_NAMES)
DATE_END = re.compile(r'\b(?:' + MONTHS + r')\.? +\d{1,2}(?:st|nd|rd|th)?,$', re.I)
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = {'in', 'on', 'at', 'of', 'to', 'for', 'from', 'by', 'with',
                'into', 'over', 'under', 'between', 'since', 'about', 'around'}
CONJUNCTIONS = {'and', 'or', 'but', 'than'}
AUXILIARIES = {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'has', 'have',
               'had', 'do', 'does', 'did', 'will', 'would', 'can', 'could'}


def space_response(prev, prev2, tail):
    """Rate the left context of one standalone ASCII space."""
    word = prev.strip().lower()
    if not tail:
        return 0.45
    elif prev == ' ':
        return 1.45 if prev2[-1:].isalpha() else 2.0
    elif prev.isspace() and '\n' not in prev and '\r' not in prev:
        return 2.85 if len(prev) > 1 else 1.2
    elif '\n' in prev or '\r' in prev:
        return 0.0
    elif tail.endswith('\\n'):
        return -0.4
    elif prev[-1:].isdigit():
        return 0.3
    elif word == ',':
        return 2.55 if DATE_END.search(tail) else (
            1.7 if prev2[-1:].isdigit() else 1.1)
    elif word == '.':
        short = prev2.strip()
        if re.search(r'(?:^|\n)[ \t>]*\d+\.$', tail):
            return 0.15
        elif short.isalpha() and (len(short) == 1 or (
                len(short) <= 4 and short[0].isupper())):
            return 1.7
        else:
            return 0.9
    elif word and word[-1] in ':;=+-*/<>|([{':
        return 1.2
    elif word and word[-1] in ')]}':
        return 0.95
    elif word == 'the':
        return 0.28
    elif word in ARTICLES:
        return 0.5
    elif word in PREPOSITIONS:
        return 0.6
    elif word in CONJUNCTIONS:
        return 0.9
    elif word in AUXILIARIES:
        return 0.68
    elif word.capitalize() in MONTH_NAMES:
        return 1.25
    else:
        return 0.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0, 0)
    # Count double spaces after words to recognize document spacing style.
    _, prev, prev2, tail, word_spaces, doubled = carry
    token = prefix.token_strings[-1]
    if token == ' ':
        value = space_response(prev, prev2, tail)
        if prev[-1:].isalpha() and not tail.endswith('\\n'):
            value -= 0.9 * min(1.0, 2 * doubled / (word_spaces + 5))
        if prev[-1:].isalpha():
            word_spaces += 1
        if prev == ' ' and prev2[-1:].isalpha():
            doubled += 1
    elif token == '\xa0':
        if prev and not prev.strip('\xa0'):
            value = 2.25 if len(prev) > 1 else 0.8
        elif prev and prev[-1] in '+-.,&)':
            value = 0.3
        else:
            value = 0.5 if '`' in prev else 0.0
    elif token == '\t':
        if not tail:
            value = -1.45
        elif prev and not prev.strip('\t'):
            value = 1.1 if len(prev) > 1 else 0.8
        else:
            value = -0.03
    elif token.strip(' ') == '``':
        value = 0.75
    elif token.strip(' ') == '`':
        value = 0.26 if token.startswith(' ') else 0.15
    else:
        value = 0.0
    return (doc, token, prev, (tail + token)[-80:], word_spaces, doubled), value

"""Recognize broken-up text at paragraph and sentence openings.

Space-only indentation after a line break gives a positive pulse, especially
following an all-capitals heading. Short lowercase fragments after a full stop,
editorial bracketed initials, and footnote abbreviations give other pulses.
NUL bytes after uppercase letters in UTF-16-like text also give positive pulses.
A separately tokenized middle byte of an Ethiopic UTF-8 character gives a
negative pulse. Initially indented fragments get a negative baseline; other
tokens stay at zero. A document-opening "Title:" field has a negative pulse.
These rules omit the component's many small lexical idiosyncrasies.
"""
import re
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, tail, byte_tail = '', '', b''
        letters, capitals, heading = 0, 0, False
    else:
        _, previous, tail, byte_tail, letters, capitals, heading = carry
    word = text.strip()
    lower = word.isascii() and word.isalpha() and word.islower()
    value = 0.0

    if first:
        if text.isspace() and text == len(text) * ' ':
            value = -0.13 if len(text) == 1 else -0.53
        elif text.startswith(' ') and lower:
            value = -0.33 if len(word) == 1 else -0.09
    elif text and text == len(text) * ' ':
        if previous.endswith('\n'):
            width = len(text)
            if previous.isspace() and len(previous) > 1:
                if width == 4:
                    value = 1.07 if heading else 0.59
                elif width == 6:
                    value = 0.62 if heading else 0.42
                elif width == 8:
                    value = 0.24
                elif width == 2 and previous == ' \n':
                    value = 0.20
            elif width == 4:
                value = 0.10 if previous.rstrip().endswith('.') else 0.05
    elif lower:
        if not text.startswith(' ') and re.search(r'\[[A-Za-z]\](?:\{\})?$', tail):
            value = 1.4
        elif word == 'fn' and tail.rstrip().endswith(('(', ')', '.')):
            value = 1.0
        elif len(word) == 1 and word not in {'a', 'i'}:
            if text.startswith(' ') and previous.endswith('.'):
                value = 0.46 if re.search(r'[A-Za-z]{3,}\.$', tail) else 0.12
            elif previous == '.\n':
                value = 0.41
            elif (previous.endswith('\n')
                  and not any(c in previous for c in '()[]{}')):
                value = 0.07
        elif (len(word) == 2 and previous.endswith('\n')
              and previous.rstrip().endswith('.')):
            value = 0.17

    if text == ':' and tail == 'Title':
        value = -3.08  # The canonical document-title metadata separator.

    raw = prefix.token_bytes[-1]
    if raw == b'\x00' and len(byte_tail) >= 2:
        if byte_tail[-2] == 0 and byte_tail[-1:].isupper():
            value = 0.89  # Uppercase ASCII in an alternating-NUL byte stream.
    elif len(raw) == 1 and byte_tail.endswith(b'\xe1'):
        if 0x80 <= raw[0] < 0xc0:
            # Lowest codepoint compatible with these first two UTF-8 bytes.
            possible = chr(0x1000 + ((raw[0] & 63) << 6))
            if regex.fullmatch(r'\p{Block=Ethiopic}', possible):
                value = -1.6

    # Keep only the current line's case counts and a short editorial-bracket tail.
    for ch in text:
        if ch == '\n':
            if letters:
                heading = letters >= 6 and capitals > 0.9 * letters
            letters = capitals = 0
        elif ch.isalpha():
            letters += 1
            capitals += ch.isupper()
    return (doc, text, (tail + text)[-16:], (byte_tail + raw)[-2:],
            letters, capitals, heading), value

"""Certainty, evidence, and qualification of assertions.

Strong negative values mark emphatic assertions; weaker values mark probability
or qualification. Recognize completed words, including split subwords, and a few
ordinary multiword qualifiers. Most other tokens receive zero. Chinese stance
markers, questions, and status predicates receive negative values too.
A few secondary patterns cover frequency phrases and document-title punctuation.
