import re

READS = ()

# These are linguistic classes, not token identifiers.
ASSERTION = set('absolutely definitely unquestionably indisputably'.split())
EVIDENCE = set('clearly obviously evidently certainly surely undoubtedly truly '
               'strictly technically unequivocally apparently'.split())
QUALIFICATION = set('necessarily genuinely presumably plainly officially virtually '
                    'hardly inherently expressly distinctly theoretically supposedly '
                    'literally really objectively honestly frankly duly'.split())
STRONG_QUALIFICATION = set('purely admittedly'.split())
PROBABILITY = set('probably possibly conceivably arguably effectively typically '
                  'normally potentially seemingly reportedly essentially '
                  'fundamentally exclusively invariably ordinarily'.split())
LIMITATION = set('actually basically merely solely wholly totally precisely '
                 'formally legally explicitly specifically practically'.split())

VALUES = {
    'assertion': -3.25, 'evidence': -2.35, 'qualification': -0.95,
    'purity': -1.8, 'probability': -0.6, 'limitation': -0.35, 'adverb': -0.045,
    'indeed': -3.7, 'Indeed': -0.7, 'modal_indeed': -5.1, 'well': -3.0, 'much': -1.5,
    'not_exactly': -2.7, 'exactly': -0.1,
    'likely': -0.5, 'comparative_likely': 0.2,
    'least_once': 3.2, 'at_once': 1.15,
    'zh_certain': -3.5, 'zh_polar_question': -3.5,
    'zh_evidence': -2.2, 'zh_stance': -1.35,
    'zh_question': -1.6, 'zh_belong': -2.0, 'zh_exist': -0.9,
    'zh_negation': -0.6, 'translation': -1.3,
    'title_colon': -8.944, 'split_evidence': -3.7,
    'split_probability': -1.2,
}


def category(tail, token):
    # Never fire again on punctuation following a completed stance word.
    if not token or not token[-1].isalpha():
        if token == ':' and tail == 'Title:':
            return 'title_colon'
        return None
    m = re.search(r'[A-Za-z]+$', tail)
    if m:
        word = m[0].lower()
        context = tail.lower()
        if m[0].isupper() and len(word) > 2:
            return None
        if word in {'clearly', 'obviously'} and re.search(
            r'\b(not|more|less|very|too|quite|rather|see|think|understand|'
            r'explain|state|communicate|describe) ' + word + r'$', context
        ):
            return 'adverb'
        if word == 'indeed':
            if re.search(
                r'\b(may|might|could|would|will|can|must|should) indeed$',
                context,
            ):
                return 'modal_indeed'
            return 'Indeed' if m[0][0].isupper() else 'indeed'
        if word == 'well' and re.search(r'\b(may|might|could)( very)? well$', context):
            return 'well'
        if word == 'much' and re.search(r'\b(pretty|very) much$', context):
            return 'much'
        if word == 'exactly':
            negated = re.search(r"(\bnot|n['’]t) exactly$", context)
            return 'not_exactly' if negated else 'exactly'
        if word == 'likely':
            comparative = re.search(r'\b(more|less|most|as) likely$', context)
            return 'comparative_likely' if comparative else 'likely'
        if word == 'once':
            if re.search(r'\bleast once$', context):
                return 'least_once'
            if re.search(r'\bat once$', context):
                return 'at_once'
        for name, words in (
            ('assertion', ASSERTION), ('evidence', EVIDENCE),
            ('qualification', QUALIFICATION), ('purity', STRONG_QUALIFICATION),
            ('probability', PROBABILITY),
            ('limitation', LIMITATION),
        ):
            if word in words:
                split = token.strip().lower() != word
                if split and name in {'evidence', 'probability'}:
                    return 'split_' + name
                return name
        if word.endswith('ly'):
            return 'adverb'
    t = token.strip()
    if t == '是不是':
        return 'zh_polar_question'
    if t in {'确实', '確實', '的确', '的確'}:
        return 'zh_certain'
    if t in {
        '真的', '我真的', '真的是', '显然', '顯然',
        '无疑', '無疑', '毕竟是', '绝对是',
    }:
        return 'zh_evidence'
    if t in {
        '其实', '其實', '到底', '究竟', '到底是', '究竟是',
        '真是', '似乎', '毕竟', '畢竟', '绝对', '絕對',
    }:
        return 'zh_stance'
    if t == '是否':
        return 'zh_question'
    if t in {'属', '屬', '属于', '屬於'}:
        return 'zh_belong'
    if t in {'存在', '不存在', '构成', '構成', '涉及', '涉嫌'}:
        return 'zh_exist'
    if t in {'不是', '并非', '並非', '并不是', '非', '不算', '算是'}:
        return 'zh_negation'
    if t in {
        'wirklich', 'wohl', 'действительно', 'вообще', 'именно',
        'realmente', '確かに', '本当に', '明らか',
        'やっぱり', 'やっぱ', 'きっと',
    }:
        return 'translation'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    tail = (tail + token)[-100:]
    text = tail.decode('utf-8', errors='replace')
    name = category(text, token.decode('utf-8', errors='replace'))
    return (doc, tail), VALUES.get(name, 0.0)

"""Predict a document-onset pulse, not an ongoing topic response.

Opening words without a preceding space have a stronger pulse. Function
words, digits and separators have weaker ones; word rarity and capitalization
modulate content words. Digits use a coarse even/odd split.
The pulse persists while the identical opening token repeats, then is zero.
The fitted class averages intentionally omit token-specific quirks.
"""
from functools import lru_cache
from wordfreq import zipf_frequency, get_frequency_dict
from math import log10
import regex
import wordnet

READS = ()

PREPOSITIONS = set('of in on at by to for from with as into over under through '
                   'between after before about without within against during '
                   'among upon'.split())
CONJUNCTIONS = set('and or but nor yet so because although though since unless '
                   'while whether than that if'.split())
AUXILIARIES = set('is are am was were be been being do does did have has had '
                  'can could may might must shall should will would cannot'.split())
PRONOUNS = set('i you he she it we they me him her us them my your his its our '
               'their mine yours hers ours theirs myself yourself himself '
               'herself itself ourselves themselves this these those what '
               'which who whom whose'.split())

# Columns: space+lowercase, space+uppercase, bare lowercase, bare uppercase.
GRAMMAR = [
    ({'the'}, (4.72, 5.56, 9.25, 10.39)),
    ({'a', 'an'}, (3.3, 3.3, 6.5, 8.1)),
    (PREPOSITIONS, (1.8, 3.0, 5.4, 6.4)),
    (CONJUNCTIONS, (2.0, 3.0, 6.0, 8.0)),
    (AUXILIARIES, (1.9, 3.0, 6.4, 7.5)),
    (PRONOUNS, (3.0, 4.2, 6.8, 9.2)),
]


@lru_cache(maxsize=8192)
def onset(text):
    w = text.strip()
    if not w:
        return 5.7 if '\t' in text else 1.7 if '\n' in text else 2.3
    if w.startswith('<|') or w.startswith('</tool_'):
        return 6.6
    if w.isdecimal():
        return 4.0 if int(w) % 2 == 0 else 2.5
    spaced = text.startswith(' ')
    if w.isascii() and w.isalpha():
        form = (0 if spaced else 2) + int(w[0].isupper())
        for words, levels in GRAMMAR:
            if w.lower() in words:
                return levels[form]
        frequency = max(2.5, min(7.5, zipf_frequency(w.lower(), 'en')))
        base = (4.0, 5.6, 7.6, 10.3)[form]
        slope = (0.7, 1.0, 0.0, 1.3)[form]
        value = base - slope * (frequency - 5)
        if form == 3:
            value -= 0.5 * (min(len(w), 8) - 4)
        parts = wordnet.parts_of_speech(w.lower())
        if 'noun' in parts:
            value += (1.6, 0.4, 0.6, 0.6)[form]
        if 'verb' in parts:
            value += (0.0, 1.2, 1.9, -0.3)[form]
        if 'adverb' in parts:
            value -= (0.8, 0.7, 0.4, -0.2)[form]
        return value
    if regex.search(r'\p{Script=Han}', w):
        frequency = log10(get_frequency_dict('zh').get(w, 1e-9)) + 9
        return (5.3 - 0.44 * (frequency - 5)
                - 0.5 * (min(len(w), 5) - 2))
    if regex.search(r'\p{Script=Cyrillic}', w):
        frequency = max(2.5, min(7.5, zipf_frequency(w.lower(), 'ru')))
        return 5.0 + 5 * w[0].isupper() - 0.7 * (frequency - 5)
    if w[0].isalpha() or '\ufffd' in w:
        return 7.3 + 1.6 * w[0].isupper()
    if w[0] in "'’" and w[1:] in {'s', 're', 've', 'll', 't', 'd', 'm'}:
        return 3.2
    if any(c.isalpha() for c in w):
        return 8.0
    if len(w) > 1 and len(set(w)) == 1:
        if not w.isascii() or (w[0] in '_*^' and len(w) <= 4):
            return 15.0
    value = 5.4 - 2.2 * spaced - 1.4 * ('\n' in text)
    if len(w) > 1:
        return value + 1.5 * (min(len(w), 5) - 1)
    if w in ',;:，；：':
        return value - 3.7
    if w in '.!?。！？':
        return value - 2.0
    if w in ')]}':
        return value - 1.4
    if w in '([{':
        return value + 1.7
    if w in "'\"":
        return value + 2.3
    if w in '_#$\\^*':
        return value + 3.1
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = onset(prefix.token_strings[-1])
        return (doc, token, True, value), value
    _, opening, repeating, value = carry
    repeating = repeating and token == opening
    return (doc, opening, repeating, value), value if repeating else 0.0

"""A small boundary-and-formatting approximation, not a semantic detector.

Most tokens get nearly zero. Document openings have a negative offset,
except programming headers and markup. Configuration/text-file suffixes
are negative; familiar domain suffixes and visible punctuation runs can
be positive. These broad rules leave substantial token-specific variation
unexplained. Only the document position needs to be carried forward.
