READS = ()

IMPORT_WORDS = {
    'package', 'namespace', 'using', 'include', 'extern', 'import', 'from',
}
CONFIG_SUFFIXES = {
    '.json', '.yaml', '.yml', '.xml', '.toml', '.ini', '.cfg', '.mod', '.sum',
}
TEXT_SUFFIXES = {'.txt', '.md', '.rst', '.csv', '.tsv', '.tex'}
DOMAIN_SUFFIXES = {'.com', '.org', '.edu', '.gov', '.net'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    position = 0 if first else carry[1] + 1
    s = prefix.token_strings[-1]
    w = s.strip()
    value = -0.0006

    if w in CONFIG_SUFFIXES:
        value -= 0.194
    if w in TEXT_SUFFIXES:
        value -= 0.149
    if w in DOMAIN_SUFFIXES:
        value += 0.170
    if len(w) >= 2 and set(w) == {'·'}:
        value += 0.339
    if len(w) >= 32 and len(set(w)) == 1 and w[0] in '-_=':
        value += 0.080

    if s in IMPORT_WORDS:
        value += 0.064
    if first:
        value -= 0.140
        if w.islower():
            value += 0.078
        if '<' in s:
            value += 0.362
        if s in IMPORT_WORDS:
            value += 0.368
        if '#' in s:
            value += 0.206
        if ',' in s:
            value -= 0.154
        if '"' in s:
            value -= 0.204
    elif position in (2, 3):
        value += 0.018

    if s == '<|im_start|>':
        value = 0.285 if first else -0.090
    return (document, position), float(value)

