Company names, citations, titles and shortened units get positive activations.
The same pieces in ordinary prose are weaker: 'al' is strong after 'et',
units after numbers, and 'v' after a capitalized name. Periods completing
some abbreviations give a negative response. US and United States also
receive positive values. These are approximate lexical rules, not a test
for a period actually following: no future text is used.
"""
import re
import calendar

READS = ()
MONTHS = set(calendar.month_abbr[1:]) - {'May'} | {'Sept'}
TITLES = {'Mr', 'Mrs', 'Ms', 'Dr', 'Prof', 'Rev', 'Hon', 'Gen',
          'Sen', 'Rep', 'Lt', 'Col', 'Capt', 'Sgt', 'Mt', 'Ft'}
COMPANIES = {'Inc', 'INC', 'Corp', 'CORP', 'Ltd', 'LTD', 'Bros', 'Pty', 'Pte'}
REFERENCES = {'Fig', 'fig', 'Figs', 'figs', 'Eq', 'eq', 'Eqs', 'eqs',
              'Ref', 'ref', 'Refs', 'refs', 'Ch', 'ch', 'Vol', 'vol',
              'Art', 'art', 'Sec', 'sec', 'pg', 'pp', 'Pg', 'Pp', 'ff', 'seq'}
OTHER = {'Ave', 'Blvd', 'Rd', 'Univ', 'Inst', 'Dept', 'Assn', 'Soc',
         'approx', 'Approx', 'spp', 'Nr', 'nr', 'cf', 'viz', 'ibid',
         'cert', 'Pub', 'Pat', 'Const', 'Civ', 'Fed', 'Ser',
         'Calif', 'Mich', 'Ind'}
UNITS = {'ft', 'mi', 'oz', 'lb', 'lbs', 'qt', 'pt', 'tsp', 'tbsp',
         'hr', 'hrs', 'min', 'Min', 'sq', 'wt', 'in', 'km', 'mm',
         'cms', 'wk', 'yr'}
# Abbreviations which can be split across several tokens.
SPLIT = {'Supp', 'Messrs', 'Mfg', 'Thm', 'Wm', 'Adm', 'Govt', 'Vt',
         'Sts', 'Drs', 'Eds', 'Figs', 'figs', 'Eqs', 'eqs', 'Refs', 'refs',
         'Profs', 'Assn', 'Esq', 'Ctr', 'Pte', 'Corp', 'CORP',
         'Etc', 'Univ', 'Dept'}
CANDIDATES = (MONTHS | TITLES | COMPANIES | REFERENCES | OTHER | UNITS |
              {'al', 'Co', 'co', 'v', 'vs', 'St', 'Jr', 'Sr', 'ed', 'eds',
               'Ed', 'No', 'Nos', 'no', 'nos', 'App', 'Cir', 'Dist', 'etc',
               'US', 'States', 'Ct', 'руб', 'ст', 'г', 'мин', 'др', 'd', 'c'})

def activation(token, before):
    s = token.lstrip()
    boundary = 1.0 if token[0].isspace() else 0.5
    if token == '.,':
        return -1.7 if before.endswith('.e') else -0.4
    if token == '.':
        return -1.0 if before.endswith('U.S') else -0.01
    if s in {'.S', '.C', '.A', '.Ed', '.Ct', '.g', '.e', '.m'}:
        if s == '.S':
            return 1.5
        if s in {'.Ct', '.Ed'}:
            return 3.9
        return 0.5
