            if word in SPLIT:
                return 2.8
            if word not in CANDIDATES:
                return 0.0
    if s not in CANDIDATES:
        return 0.0
    words = re.findall(r'[\w]+', before[-60:])
    last = words[-1] if words else ''
    name = ((last.istitle() or last.isupper()) and len(last) > 1
            and last not in {'The', 'This', 'That', 'In', 'On', 'For', 'Of',
