                             'Is', 'An', 'At',
                             'Let', 'However', 'But', 'Das', 'Die',
                             'Der', 'Und',
                             'Vector'})
    number = bool(re.search(
        r'(?:\d|sq\.?|square|cub\.?|cubic|million|billion)\s*$', before))
    if s == 'al':
        return 4.3 if last == 'et' else 0.02
    if s == 'v':
        if name and token[0].isspace():
            return 1.8
        return 0.04
    if s == 'vs':
        return 1.1
    if s == 'co':
        return 0.8
    if s == 'Co':
        company_context = name or before.rstrip().endswith('&')
        return (3.9 if company_context else 1.6) * boundary
    if s in COMPANIES:
        return 2.5 if s in {'Ltd', 'LTD', 'Pty'} else 3.9
    # Number labels and editorial/legal citations.
    if s in {'No', 'Nos', 'no', 'nos'}:
        if last in {'Pat', 'Patent', 'patent', 'Reissue'}:
            return 5.7
        if last in {'Case', 'case', 'ECF', 'Docket', 'Serial', 'Application',
                    'Registration', 'Order', 'Appeal', 'Doc',
                    'Publication', 'Ser',
                    'File', 'Contract', 'Amendment', 'Memorandum',
                    'ATCC', 'accession'}:
            return 3.6
        if s == 'Nos':
            return 2.4
        return 0.8 if s == 'No' and token[0].isspace() else 0.2
    if s == 'Ed':
        return 0.9
    if s in {'ed', 'eds'}:
        if re.search(r'\d+(?:st|nd|rd|th)\s*$', before):
            return 10.1
        if s == 'eds':
            return 5.9
        if (before.rstrip().endswith(('(', ','))
                or last in {'rev', 'revised', 'First', 'Second', 'third'}):
            return 3.7
        return 0.9
    if s in {'Cir', 'Dist'}:
        return 6.4 if re.search(r'\d+(?:st|nd|rd|th|d)\s*$', before) else 2.0
    if s == 'St':
        return 5.2 if re.search(r'\d+(?:st|nd|rd|th)\s*$', before) else 1.2
    if s in {'Jr', 'Sr'}:
        return 4.7 if s == 'Jr' else 1.9
    if s in TITLES:
        return 1.2
    if s in MONTHS:
        return 0.7
    if s in REFERENCES:
        if s in {'pp', 'Pp', 'pg', 'Pg', 'ff'}:
            return 2.2 if token[0].isspace() else 0.3
        if s in {'Fig', 'fig', 'Figs', 'figs', 'Eq', 'eq',
                 'Eqs', 'eqs', 'Ref', 'ref', 'Refs', 'refs'}:
            return (1.2 if s.lower().startswith('fig') else 0.5) * boundary
        return (0.5 * boundary) if s in {'Ch', 'ch'} else (0.3 * boundary)
    # A quantity disambiguates shortened measurement units.
    if s in UNITS:
        if s == 'in':
            return 0.4 if number else 0.0
        if number:
            if s in {'km', 'mm', 'cms'}:
                return 0.4
            if s in {'ft', 'mi'}:
                return 3.7
            return 1.5 if s in {'min', 'Min'} else 2.4
        return 0.5
    if s == 'etc':
        return 1.6
    if s in OTHER:
        if s in {'Univ', 'Inst', 'Ave', 'Blvd', 'Rd', 'spp'}:
            return 3.2
        return 0.8
    if s == 'Ct':
        return 4.0 if last == 'S' else 0.8
    if s == 'US' or s == 'States' and last == 'United':
        return 1.0
    if s in {'руб', 'ст', 'г', 'мин', 'др'}:
        return 2.0 if s == 'руб' else 0.4
    if s == 'App':
        return 1.2
    if s == 'c' and before.rstrip().endswith('&'):
        return 1.6
    if s == 'd' and before.endswith(('2', '3')):
        return 2.2 if re.search(r'(?:\.\s*|\(\s*)[23]$', before) else 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, before)
    return (doc, (before + token)[-160:]), float(value)

"""Strong lexical responses to Vietnamese motion and location words.

Thai reach/become/new/rise constructions are recognized across token splits.
Spelling a Vietnamese word in pieces can increase the completion response.
A few document-opening formatting and number transients are separate cases;
the remaining, much smaller and heterogeneous responses are left at zero.
"""
import re

READS = ()

# Vietnamese motion, continuation, and location words.
VIETNAMESE = {
    'đến': 5.3,   # arrive / to
    'tới': 4.8,   # reach / towards
    'đi': 2.3,    # go
    'thêm': 2.0,  # add / more
    'lại': 0.9,   # back / again
    'tiếp': 0.5,  # continue / next
    'tái': 1.0,   # re-
    'cùng': 0.9,  # together / with
    'bên': 2.1,   # side / beside
    'lên': 1.7,   # up
    'trên': 0.9,  # above / on
    'xuống': 0.7, # down
    'dưới': 0.5,  # below
    'giữa': 0.6,  # between
    'về': 0.35,   # back towards / about
    'vào': 0.4,   # into
    'ra': 0.3,    # out
}
SPLIT_COMPLETIONS = {'đến': 10.8, 'trên': 9.0, 'lên': 6.5, 'đi': 3.7}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, count = '', 0
    else:
        _, previous, count = carry
    token = prefix.token_strings[-1]
    text = previous + token
    match = re.search(r'([^\W\d_]+)$', text)
    word = match[1].casefold() if match else ''
    value = 0.0
    if word in VIETNAMESE:
        value = VIETNAMESE[word]
        if word != token.strip().casefold():
            value = SPLIT_COMPLETIONS.get(word, value)
        elif token.strip()[:1].isupper():
            value *= 1.3
        if previous.rstrip()[-1:].isdigit():
            value *= 0.6
        if word == 'về' and previous.rstrip().endswith('trả'):
            value = 2.9  # trả về: return
    elif text.endswith('ถึง'):
        value = 2.5  # reach / to
    elif text.endswith('ตึง'):
        value = 1.6  # tight / tense
    elif text.endswith('เป็น'):
        value = 0.15 if text.endswith('จำเป็น') else 1.15  # must vs be
    elif text.endswith('ใหม่'):
        value = 1.9  # new / again
    elif text.endswith('ขึ้น'):
        value = 1.5  # rise / up
    if count == 1 and previous == '1' and token == '2':
        value = -3.84
    if count == 0:
        if '\\' in token:
            value = 1.9
        elif token in ('--', '-\n'):
            value = 1.2
        elif token.strip() and set(token.strip()) == {'#'}:
            value = 0.6
        elif token.isspace() and '\n' in token:
            value = 0.3
    return (doc, text[-24:], count + 1), value

"""A local grammar approximation, not a token-identity lookup.

The strongest negative responses are copulas in conditional/time clauses
('if you are', 'when we're'), -ing words after 'when', and the first
article or -ing word after 'you/we' + copula following a clause marker.
Modals in these contexts are positive.
Split English words are joined causally as their pieces arrive.
There are smaller responses to ordinary personal copulas, progressives,
'in the case of', examples of domains/settings, and 'especially'. Values are
rounded training averages. Small grammatical and formatting offsets are
added; most lexical variation is left unexplained.
"""
from functools import lru_cache
import wordnet

READS = ()
CLAUSES = {
    'if': 'condition', 'unless': 'condition', 'whether': 'condition',
    'suppose': 'condition', 'when': 'time', 'whenever': 'time',
    'until': 'time', 'since': 'cause', 'because': 'cause',
    'while': 'contrast', 'although': 'contrast', 'though': 'contrast',
    'as': 'as', 'who': 'relative',
}
BE = {'am', 'is', 'are', 'was', 'were', "'m", "'s", "'re"}
MODALS = set('can could may might must shall should will would'.split())
PRONOUNS = set('i you we he she it they there'.split())
DOMAINS = set(
    'case cases field fields area areas sector sectors industry industries '
    'application applications task tasks project projects context contexts '
    'situation situations environment environments domain domains '
    'country countries city cities setting settings'.split()
)
# Columns: you/we + are, you/we + 're, other you/we copula, other subject.
COPULAS = {
    'condition': (-.96, -.70, -.55, -.16),
    'time': (-.69, -.64, -.22, -.10),
    'cause': (-.41, -.38, -.11, -.12),
    'contrast': (-.22, -.40, -.20, -.03),
    'as': (-.19, -.20, -.10, -.02),
    'relative': (-.08, -.10, -.10, -.13),
}

@lru_cache(maxsize=20000)
def is_verb(word):
    return word.isascii() and word.isalpha() and (
        'verb' in wordnet.parts_of_speech(word)
    )


def predict(history, word):
    previous = history[-1] if history else ''
    gerund = len(word) > 4 and word.isalpha() and word.endswith('ing')
    if word == 'of' and previous in {'case', 'cases'} and 'in' in history:
        return -.56
    if word == 'an' and previous == 'such':
        return -.15
    if word == 'like' and previous in DOMAINS:
        return -.57
    if word == 'especially':
        return -.23

    marker = None
    for distance, token in enumerate(reversed(history), 1):
        if token in CLAUSES:
            marker = CLAUSES[token]
            break
        if any(ch in token for ch in ',;.!?\n'):
            break
    if marker and distance <= 6:
        if word in BE:
            if marker == 'relative' and word == 'are':
                return -.32
            column = 3
            if previous in {'you', 'we'}:
                column = 0 if word == 'are' else 1 if word == "'re" else 2
            return COPULAS[marker][column]
        if word in MODALS and previous in PRONOUNS:
            if word == 'can':
                return .40 if previous == 'you' else .30
            return .27 if word == 'could' else .06
        if word in {'have', 'has', 'had', "'ve"} and previous in PRONOUNS:
            return -.13
        if gerund and distance == 1:
            return {'time': -.42, 'contrast': -.18,
                    'condition': -.09}.get(marker, -.001)
        if previous in BE:
            personal = len(history) > 1 and history[-2] in {'you', 'we'}
            if gerund:
                return -.62 if personal else -.12
            if word in {'a', 'an', 'the'}:
                return -.71 if personal else -.05
        if word in {'not', "n't"}:
            return .06
        if distance == 1 and word in {'so', 'possible', 'necessary'}:
            return .14
        if word == 'we' and distance == 1:
            return -.03
        if previous in PRONOUNS and is_verb(word):
            return -.15 if previous in {'you', 'we'} and (
                marker in {'time', 'cause'}
            ) else -.07

    if word in BE:
        if previous in {'you', 'we'}:
            return -.14
        if previous == 'i':
            return -.11
        if previous in {'this', 'that'}:
            return .03
        if previous == 'which':
            return -.07
    if word == 'be' and previous in MODALS:
        return .02
    if gerund and previous in BE:
        personal = len(history) > 1 and history[-2] in {'i', 'you', 'we'}
        return -.17 if personal else -.02
    return -.001


@lru_cache(maxsize=20000)
def lexical_offset(word):
    """Weak background effects, separate from the sharp clause responses."""
    if word in {'的', 'の'}:  # Chinese/Japanese genitive particles
        return -.05
    if word in {'other', 'another'}:
        return .06
    if word == 'our':
        return .05
    if word in {'its', 'their'}:
        return -.03
    if word in {'may', 'might'}:
        return -.04
    if word in {'must', 'shall', 'should'}:
        return .03
    if len(word) > 1 and set(word) == {'·'}:
        return .26
    if word == '</think>':
        return -.12
    if word.isascii() and word.isalpha():
        roots = wordnet.base_forms(word)
        if 'work' in roots:
            return -.07
        if 'look' in roots:
            return -.03
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    history = carry[1] if same_doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().replace('’', "'")
    letters = word.isascii() and word.isalpha()
    # A token without a leading separator can finish the previous word.
    if same_doc and carry[2] and letters and raw[:1].isalpha():
        word = history[-1] + word
        history = history[:-1]
    value = predict(history, word) + lexical_offset(word)
    if not word and "\n" in raw and history and history[-1] == "</think>":
        value = -.08
    continues_word = letters and raw[-1:].isalpha()
    return (doc, (history + (word,))[-10:], continues_word), value

programs.haiku:
"""Layer-1 MLP down-projection component 6077: a small, mostly negative, diffuse feature.

What it responds to, in plain terms:
  - Strongest: the verb right after a subject pronoun, when that verb is a form of "be".
    "If you ARE ...", "when we'RE ...", "if I WAS ..." push it negative (most for are/'re/were).
  - Doing-verbs after a subject ("you USE", "you DO") are negative too.
  - Modal verbs right after a subject ("you CAN", "we MUST", "you SHOULD") are mildly positive.
  - Any word right after "when" is mildly negative ("when WORKING", "when USING").
  - Ordinary -ing words are slightly negative.
  - Everything else is predicted as 0.
Values are typical activations (not tuned to the eval set); the rule explains only a small
share of the variance, because most of the component's activity is diffuse and token-specific.
"""

READS = ()

SUBJECTS = {"you", "we", "i", "who", "they"}
BE_STRONG = {"are", "'re", "’re", "were"}
BE_WEAK = {"is", "was", "am", "'m", "’m"}
DO_VERBS = {"use", "do", "using", "working", "did"}
MODALS = {"can", "must", "should", "could", "will", "would", "need"}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    cur = prefix.token_strings[-1].strip().lower()
    if prev in SUBJECTS:
        if cur in BE_STRONG:
            return carry, -0.24
        if cur in BE_WEAK:
            return carry, -0.135
        if cur in DO_VERBS:
            return carry, -0.14
        if cur in MODALS:
            return carry, 0.065
        return carry, 0.0
    if prev == "when":
        return carry, -0.06
    if cur.endswith("ing") and len(cur) > 4:
        return carry, -0.024
    return carry, 0.0

programs.sol:
"""Recognize short je/ji fragments, including a j split from its vowel.

The response to ``je`` is language-sensitive: strong in German and Dutch,
weak in French and Slavic text. Recent word frequencies estimate language.
There are also responses to the Japanese/Korean syllables ji/je, the
Chinese/Japanese aid/settle, ford and pearl characters, and the euro sign.
Repeated middle dots get a small negative response; other tokens are near zero.
This is a selective orthographic approximation, not a general sound detector.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'nl', 'fr', 'cs', 'pl', 'sk', 'sl',
             'es', 'pt', 'it', 'nb', 'sv', 'da', 'hu', 'lt', 'id', 'tr', 'ru')

@lru_cache(maxsize=12000)
def word_scores(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language(text):
    text = text.rsplit('<|endoftext|>', 1)[-1]
    text = re.sub(r'<\|[^>]+\|>(?:user|assistant|system)?', ' ', text)
    words = re.findall(r'[^\W\d_]+', text.lower())[-40:]
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        if len(word) > 1:
            scores = [a + b for a, b in zip(scores, word_scores(word))]
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        context, previous = b'', b''
    else:
        _, context, previous = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'replace')
    s = token.strip()
    lower = s.lower()
    text = context.decode('utf-8', 'replace')
    tail = (context[-8:] + raw).decode('utf-8', 'replace')
    value = -0.003

    # A small collection of orthographic forms, not all words containing j.
    if re.fullmatch(r'(?:[ai]?j[ie]|j[ie]s|jie)', lower):
        lang = language(text)
        leading = token[:1].isspace() or (s[:1].isupper()
                                          and not text[-1:].isalpha())
        if lower == 'ji':
            value = 5.0 if leading else (3.3 if s.isupper() else 6.3)
            if lang in ('pl', 'sk'):
                value = 0.4
            elif lang == 'cs':
                value = 1.5 if leading else 3.2
            elif lang == 'id':
                value = 2.6
            elif lang == 'tr':
                value = 1.2
        elif lower in ('aji', 'iji', 'jie'):
            value = {'aji': 4.0, 'iji': 2.1, 'jie': 3.0}[lower]
        elif lower == 'aje':
            value = 2.5 if lang == 'en' else 0.1
        elif lower == 'jes':
            value = {'nl': 4.3, 'de': 0.7, 'hu': 0.1}.get(lang, 1.4)
        elif lower == 'jis':
            value = 0.0
        else:
            if leading:
                value = {'de': 6.6, 'nl': 4.4, 'fr': 1.3,
                         'cs': 0.4, 'sk': 0.4, 'pl': 0.6}.get(lang, 2.0)
                if s[:1].isupper():
                    value += 1.1
            else:
                value = {'de': 2.5, 'nl': 4.4, 'fr': 1.0,
                         'cs': 0.2, 'sk': 0.2, 'pl': 0.1,
                         'es': 0.1, 'pt': 0.1, 'ru': 0.3}.get(lang, 2.2)
                # A suffix on a capitalized name is unlike a common inflection.
                word = re.search(r'([^\W\d_]+)$', text)
                if (lang in ('en', 'fr') and lower == 'je' and word
                        and word[0][0].isupper() and len(word[0]) > 2):
                    value = 5.7
                if lang == 'nl' and text.endswith('i'):
                    value = 0.6  # Dutch ij is a vowel digraph, not a j onset.
                if s[:1].isupper():
                    value = max(value, 2.0)

    # The j may belong to the previous token (e.g. J + EE or Taj + i).
    elif previous.lower().endswith(b'j') and raw[:1].lower() in b'aeiou':
        if lower.startswith('ee'):
            value = 10.5 if s.isupper() or previous.endswith(b'j') else 8.0
        elif lower.startswith('i'):
            value = 0.6
            if lower == 'i':
                value = 6.0 if previous.endswith(b'J') else 3.2
        elif lower == 'e':
            value = 3.0
        elif lower == 'es':
            value = 2.0
        elif lower.endswith('i') and len(s) <= 4:
            value = 1.6
        else:
            value = -0.1

    if s == '€':
        value = 3.3 if token[:1].isspace() else 1.5
    elif s == 'じ':
        value = 0.3 if text.endswith('生') else 2.5
        if text.endswith(('お', '通')):
            value = 4.4
    elif s == '제':
        value = 1.9
    elif tail.endswith('済'):
        value = 5.0 if text.rstrip('�').endswith('経') else 10.5
    elif s in ('济', '濟'):
        value = 0.3 if text.endswith('经') else 7.0
        if text.endswith('共'):
            value = 12.0
    elif s == '津':  # ford; common in Chinese and Japanese place names
        value = 6.5
    elif s == '珠':  # pearl
        value = 6.5
    elif token == 'и' and text.endswith('дж'):
        value = 6.0
    elif s and set(s) == {'·'} and len(s) > 1:
        value = -0.22 * len(s)
    elif raw == '済'.encode('utf-8')[:-1]:
        # This partial byte token begins 済 as well as neighboring water kanji.
        value = 3.0

    return (doc, (context + raw)[-1200:], raw), float(value)
